const RAW_QUESTIONS = [
  [1, "p1", "Theo quan điểm của chủ nghĩa Mác – Lênin, nguyên nhân sâu xa dẫn đến sự ra đời của Nhà nước là:", ["Sự xuất hiện của tôn giáo và nhu cầu quản lý cộng đồng.", "Sự phát triển của lực lượng sản xuất dẫn đến chế độ tư hữu và sự phân hóa giai cấp đối kháng.", "Nhu cầu chống giặc ngoại xâm và trị thủy.", "Sự thỏa thuận tự nguyện giữa các thành viên trong thị tộc."], 1, "Theo chủ nghĩa Mác – Lênin, nguyên nhân sâu xa là sự phát triển của LLSX dẫn đến dư thừa của cải, xuất hiện tư hữu và phân hóa giai cấp đối kháng."],
  [2, "p1", "Bản chất của Nhà nước bao gồm hai thuộc tính cơ bản nào?", ["Tính giai cấp và tính xã hội.", "Tính cưỡng chế và tính tự nguyện.", "Tính quyền lực và tính dân chủ.", "Tính thống nhất và tính phân quyền."], 0, "Bản chất Nhà nước thể hiện ở hai thuộc tính cơ bản gắn bó chặt chẽ: tính giai cấp và tính xã hội."],
  [3, "p1", "Chức năng đối nội và chức năng đối ngoại của Nhà nước được phân loại căn cứ vào:", ["Lĩnh vực hoạt động của Nhà nước.", "Phạm vi lãnh thổ tác động của quyền lực nhà nước.", "Hình thức thực hiện quyền lực nhà nước.", "Tính chất pháp lý của hoạt động nhà nước."], 1, "Căn cứ vào phạm vi lãnh thổ tác động của quyền lực nhà nước, chức năng Nhà nước chia thành đối nội và đối ngoại."],
  [4, "p1", "Hình thức nhà nước bao gồm ba yếu tố cấu thành nào?", ["Hình thức chính thể, hình thức cấu trúc nhà nước và chế độ chính trị.", "Lập pháp, hành pháp và tư pháp.", "Trung ương, địa phương và cơ sở.", "Quân chủ, cộng hòa và liên bang."], 0, "Hình thức nhà nước được hợp thành từ 3 yếu tố: hình thức chính thể, hình thức cấu trúc nhà nước và chế độ chính trị."],
  [5, "p1", "Hình thức chính thể của Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam là:", ["Quân chủ lập hiến.", "Cộng hòa tổng thống.", "Cộng hòa xã hội chủ nghĩa.", "Cộng hòa đại nghị."], 2, "Nhà nước ta có hình thức chính thể là Cộng hòa xã hội chủ nghĩa."],
  [6, "p1", "Xét về hình thức cấu trúc nhà nước, Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam là:", ["Nhà nước liên bang.", "Nhà nước đơn nhất.", "Nhà nước liên minh.", "Nhà nước tự trị."], 1, "Việt Nam là nhà nước đơn nhất, có một hệ thống pháp luật thống nhất và một hệ thống cơ quan quyền lực từ trung ương đến địa phương."],
  [7, "p1", "Chế độ chính trị của Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam được thực hiện bằng phương pháp:", ["Phản dân chủ.", "Dân chủ xã hội chủ nghĩa.", "Độc tài chuyên chế.", "Quân chủ chuyên chế."], 1, "Chế độ chính trị của nước CHXHCN Việt Nam được thực hiện bằng phương pháp dân chủ xã hội chủ nghĩa."],
  [8, "p1", "Trong bộ máy nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam, quyền lực nhà nước được tổ chức theo nguyên tắc nào?", ["Tam quyền phân lập tuyệt đối.", "Quyền lực nhà nước là thống nhất, có sự phân công, phối hợp, kiểm soát giữa các cơ quan nhà nước trong việc thực hiện các quyền lập pháp, hành pháp, tư pháp.", "Tập trung toàn bộ quyền lực vào Chính phủ.", "Phân quyền cát cứ theo từng địa phương."], 1, "Theo Điều 2 Hiến pháp 2013, quyền lực nhà nước là thống nhất, có sự phân công, phối hợp, kiểm soát giữa các cơ quan thực hiện lập pháp, hành pháp, tư pháp."],
  [9, "p1", "Đặc điểm nào sau đây KHÔNG phải là đặc trưng cơ bản của pháp luật?", ["Tính quy phạm phổ biến.", "Tính xác định chặt chẽ về mặt hình thức.", "Tính được bảo đảm thực hiện bằng Nhà nước.", "Tính tự phát, hình thành hoàn toàn dựa trên thói quen tâm lý cá nhân."], 3, "Pháp luật do Nhà nước ban hành hoặc thừa nhận, không hình thành tự phát theo thói quen tâm lý cá nhân."],
  [10, "p1", "Ba hình thức pháp luật chủ yếu tồn tại trong lịch sử và hiện nay là:", ["Tập quán pháp, tiền lệ pháp và văn bản quy phạm pháp luật.", "Hiến pháp, luật và nghị định.", "Đạo đức, tôn giáo và pháp luật.", "Hương ước, điều lệ và nội quy."], 0, "Ba hình thức pháp luật chủ yếu trong lịch sử và hiện nay là tập quán pháp, tiền lệ pháp (án lệ) và văn bản quy phạm pháp luật."],
  [11, "p1", "Tiền lệ pháp (án lệ) là hình thức pháp luật được tạo thành từ việc:", ["Quốc hội ban hành đạo luật mới.", "Nhà nước thừa nhận các bản án, quyết định giải quyết vụ việc cụ thể của Tòa án hoặc cơ quan hành chính làm khuôn mẫu để giải quyết các vụ việc tương tự về sau.", "Cộng đồng dân cư tự thỏa thuận quy tắc ứng xử.", "Chính phủ ban hành nghị định hướng dẫn thi hành luật."], 1, "Tiền lệ pháp (án lệ) là việc Nhà nước thừa nhận các bản án, quyết định giải quyết vụ việc cụ thể làm khuôn mẫu giải quyết vụ việc tương tự về sau."],
  [12, "p1", "Tập quán pháp là hình thức pháp luật được tạo thành từ việc:", ["Nhà nước ban hành văn bản quy phạm pháp luật mới.", "Nhà nước thừa nhận một số tập quán lưu truyền trong xã hội và nâng lên thành quy tắc xử sự chung được Nhà nước bảo đảm thực hiện.", "Tòa án giải quyết một vụ việc cụ thể chưa có luật.", "Các bên tự thỏa thuận trong hợp đồng."], 1, "Tập quán pháp là việc Nhà nước thừa nhận tập quán lưu truyền trong xã hội và nâng lên thành quy tắc xử sự chung được bảo đảm thực hiện."],
  [13, "p1", "Cơ cấu của một quy phạm pháp luật thông thường gồm ba bộ phận nào?", ["Mở đầu, nội dung, kết luận.", "Giả định, quy định, chế tài.", "Chủ thể, khách thể, nội dung.", "Điều, khoản, điểm."], 1, "Cơ cấu đầy đủ của một quy phạm pháp luật gồm 3 bộ phận: Giả định, Quy định và Chế tài."],
  [14, "p1", "Bộ phận nào của quy phạm pháp luật nêu lên hoàn cảnh, điều kiện có thể xảy ra trong thực tế cuộc sống mà khi gặp hoàn cảnh, điều kiện đó thì chủ thể phải xử sự theo quy định?", ["Giả định.", "Quy định.", "Chế tài.", "Mệnh lệnh."], 0, "Giả định nêu lên chủ thể, hoàn cảnh, điều kiện xảy ra trong thực tế để áp dụng quy phạm pháp luật."],
  [15, "p1", "Chế tài trong quy phạm pháp luật có vai trò gì?", ["Nêu lên hoàn cảnh, điều kiện áp dụng quy phạm.", "Nêu lên cách xử sự mà chủ thể được làm hoặc phải làm.", "Dự kiến những biện pháp tác động bất lợi mà Nhà nước sẽ áp dụng đối với chủ thể không thực hiện đúng quy định.", "Giải thích thuật ngữ chuyên môn trong văn bản."], 2, "Chế tài dự kiến các biện pháp tác động bất lợi (hậu quả pháp lý) áp dụng đối với chủ thể không thực hiện đúng quy định."],
  [16, "p1", "Căn cứ vào tính chất mệnh lệnh, quy phạm pháp luật được chia thành:", ["Quy phạm dứt khoát và quy phạm không dứt khoát (tùy nghi).", "Quy phạm nội dung và quy phạm hình thức.", "Quy phạm chung và quy phạm riêng.", "Quy phạm luật công và quy phạm luật tư."], 0, "Căn cứ vào tính chất mệnh lệnh, quy phạm pháp luật chia thành quy phạm dứt khoát và quy phạm không dứt khoát (tùy nghi)."],
  [17, "p1", "Hệ thống cấu trúc bên trong của hệ thống pháp luật bao gồm các yếu tố sắp xếp theo trật tự từ nhỏ đến lớn là:", ["Ngành luật → Chế định pháp luật → Quy phạm pháp luật.", "Quy phạm pháp luật → Chế định pháp luật → Ngành luật.", "Chế định pháp luật → Quy phạm pháp luật → Ngành luật.", "Văn bản luật → Văn bản dưới luật → Quy phạm pháp luật."], 1, "Cấu trúc bên trong của hệ thống pháp luật từ nhỏ đến lớn: Quy phạm pháp luật → Chế định pháp luật → Ngành luật."],
  [18, "p1", "Theo Luật Ban hành văn bản quy phạm pháp luật (năm 2025), văn bản quy phạm pháp luật có hiệu lực pháp lý cao nhất trong hệ thống pháp luật Việt Nam là:", ["Bộ luật, Luật.", "Hiến pháp.", "Nghị quyết của Quốc hội.", "Pháp lệnh của Ủy ban Thường vụ Quốc hội."], 1, "Hiến pháp là đạo luật cơ bản, có hiệu lực pháp lý cao nhất trong hệ thống pháp luật Việt Nam."],
  [19, "p1", "Văn bản quy phạm pháp luật nào sau đây thuộc thẩm quyền ban hành của Ủy ban Thường vụ Quốc hội?", ["Hiến pháp, Bộ luật, Luật.", "Pháp lệnh, Nghị quyết.", "Nghị định.", "Thông tư."], 1, "Ủy ban Thường vụ Quốc hội có thẩm quyền ban hành Pháp lệnh và Nghị quyết."],
  [20, "p1", "Trong trường hợp các văn bản quy phạm pháp luật có quy định khác nhau về cùng một vấn đề thì áp dụng văn bản nào?", ["Văn bản được ban hành sau cùng.", "Văn bản có hiệu lực pháp lý cao hơn.", "Văn bản của cơ quan chuyên môn.", "Văn bản có lợi hơn cho cơ quan quản lý."], 1, "Khi các văn bản QPPL có quy định khác nhau về cùng một vấn đề thì áp dụng văn bản có hiệu lực pháp lý cao hơn."],
  [21, "p1", "Quan hệ pháp luật là quan hệ xã hội được điều chỉnh bởi:", ["Quy phạm đạo đức.", "Phong tục, tập quán.", "Quy phạm pháp luật.", "Điều lệ của các tổ chức xã hội."], 2, "Quan hệ pháp luật là quan hệ xã hội được các quy phạm pháp luật điều chỉnh, trong đó các bên có quyền và nghĩa vụ pháp lý."],
  [22, "p1", "Cấu thành của một quan hệ pháp luật bao gồm:", ["Chủ thể, khách thể và nội dung (quyền và nghĩa vụ pháp lý).", "Giả định, quy định và chế tài.", "Mặt khách quan, mặt chủ quan, chủ thể và khách thể.", "Hành vi, hậu quả và mối quan hệ nhân quả."], 0, "Cấu thành của quan hệ pháp luật gồm 3 yếu tố: Chủ thể, Khách thể và Nội dung (quyền, nghĩa vụ pháp lý)."],
  [23, "p1", "Năng lực chủ thể của chủ thể quan hệ pháp luật bao gồm hai yếu tố nào?", ["Năng lực pháp luật và năng lực hành vi.", "Năng lực nhận thức và năng lực tài chính.", "Năng lực trách nhiệm hình sự và năng lực hành vi dân sự.", "Quyền chủ thể và nghĩa vụ pháp lý."], 0, "Năng lực chủ thể bao gồm năng lực pháp luật và năng lực hành vi."],
  [24, "p1", "Năng lực pháp luật của cá nhân xuất hiện từ khi nào?", ["Khi cá nhân đủ 18 tuổi.", "Khi cá nhân sinh ra.", "Khi cá nhân đủ 15 tuổi.", "Khi cá nhân có khả năng nhận thức và điều khiển hành vi."], 1, "Năng lực pháp luật của cá nhân có từ khi người đó sinh ra và chấm dứt khi người đó chết."],
  [25, "p1", "Sự kiện pháp lý bao gồm hai nhóm nào?", ["Hành vi pháp lý và sự biến pháp lý.", "Hành vi hợp pháp và hành vi bất hợp pháp.", "Sự kiện tự nhiên và sự kiện xã hội.", "Quyền chủ thể và nghĩa vụ pháp lý."], 0, "Sự kiện pháp lý được chia làm hai nhóm: hành vi pháp lý (phụ thuộc ý chí con người) và sự biến pháp lý (không phụ thuộc ý chí con người)."],
  [26, "p1", "Hiện tượng thiên tai (bão, lũ lụt) làm chấm dứt nghĩa vụ hợp đồng được xếp vào loại sự kiện pháp lý nào?", ["Hành vi pháp lý hợp pháp.", "Hành vi pháp lý bất hợp pháp.", "Sự biến pháp lý.", "Quy phạm pháp luật."], 2, "Thiên tai như bão, lũ lụt xảy ra khách quan ngoài ý chí con người nên là sự biến pháp lý."],
  [27, "p1", "Có mấy hình thức thực hiện pháp luật cơ bản?", ["2 hình thức.", "3 hình thức.", "4 hình thức (Tuân thủ pháp luật, thi hành pháp luật, sử dụng pháp luật và áp dụng pháp luật).", "5 hình thức."], 2, "Có 4 hình thức thực hiện pháp luật cơ bản: tuân thủ, thi hành, sử dụng và áp dụng pháp luật."],
  [28, "p1", "Hình thức thực hiện pháp luật nào đòi hỏi chủ thể phải kiềm chế không thực hiện những hành vi mà pháp luật cấm?", ["Tuân thủ pháp luật.", "Thi hành pháp luật.", "Sử dụng pháp luật.", "Áp dụng pháp luật."], 0, "Tuân thủ pháp luật là việc chủ thể kiềm chế, không thực hiện những hành vi mà pháp luật cấm."],
  [29, "p1", "Hình thức thực hiện pháp luật nào chỉ do các cơ quan nhà nước, nhà chức trách có thẩm quyền hoặc tổ chức xã hội được Nhà nước trao quyền thực hiện?", ["Tuân thủ pháp luật.", "Thi hành pháp luật.", "Sử dụng pháp luật.", "Áp dụng pháp luật."], 3, "Áp dụng pháp luật là hình thức chỉ do cơ quan nhà nước, người có thẩm quyền hoặc tổ chức được trao quyền thực hiện."],
  [30, "p1", "Dấu hiệu nào sau đây KHÔNG phải là dấu hiệu cơ bản của vi phạm pháp luật?", ["Là hành vi xác định của con người.", "Trái pháp luật, xâm hại các quan hệ xã hội được pháp luật bảo vệ.", "Có lỗi của chủ thể thực hiện hành vi.", "Chỉ cần có suy nghĩ, ý định phạm tội trong đầu dù chưa bộc lộ ra hành vi."], 3, "Vi phạm pháp luật phải là hành vi xác định bộc lộ ra bên ngoài; suy nghĩ trong đầu không bị coi là vi phạm pháp luật."],
  [31, "p1", "Yếu tố nào sau đây thuộc mặt chủ quan của vi phạm pháp luật?", ["Hành vi trái pháp luật.", "Hậu quả thiệt hại cho xã hội.", "Lỗi, động cơ, mục đích vi phạm.", "Thời gian, địa điểm thực hiện hành vi."], 2, "Mặt chủ quan của vi phạm pháp luật gồm lỗi, động cơ và mục đích vi phạm."],
  [32, "p1", "Lỗi cố ý trực tiếp là trường hợp chủ thể vi phạm pháp luật:", ["Nhận thức rõ hành vi của mình là nguy hiểm cho xã hội, thấy trước hậu quả và mong muốn hậu quả đó xảy ra.", "Nhận thức rõ hành vi của mình là nguy hiểm, thấy trước hậu quả nhưng không mong muốn mà có ý thức để mặc cho hậu quả xảy ra.", "Thấy trước hậu quả nhưng tin rằng hậu quả sẽ không xảy ra.", "Không thấy trước hậu quả mặc dù phải thấy trước và có thể thấy trước."], 0, "Lỗi cố ý trực tiếp: chủ thể nhận thức rõ hành vi nguy hiểm, thấy trước hậu quả và mong muốn hậu quả xảy ra."],
  [33, "p1", "Có mấy loại trách nhiệm pháp lý cơ bản trong hệ thống pháp luật Việt Nam?", ["2 loại (Hình sự và Dân sự).", "3 loại (Hình sự, Dân sự và Hành chính).", "4 loại (Hình sự, Dân sự, Hành chính và Kỷ luật).", "5 loại."], 2, "Có 4 loại trách nhiệm pháp lý cơ bản: trách nhiệm hình sự, dân sự, hành chính và kỷ luật."],
  [34, "p1", "Ý thức pháp luật bao gồm hai bộ phận cấu thành cơ bản nào?", ["Tư tưởng pháp luật và tâm lý pháp luật.", "Tri thức pháp luật và hành vi pháp luật.", "Đạo đức và pháp luật.", "Niềm tin và kỷ luật."], 0, "Ý thức pháp luật gồm hai bộ phận cơ bản: tư tưởng pháp luật (hệ tư tưởng) và tâm lý pháp luật."],
  [35, "p1", "Nguyên tắc pháp chế xã hội chủ nghĩa đòi hỏi:", ["Chỉ công dân phải tuân thủ pháp luật, còn cơ quan nhà nước có thể linh hoạt.", "Mọi cơ quan nhà nước, tổ chức kinh tế, tổ chức xã hội, đơn vị vũ trang nhân dân và mọi công dân đều phải nghiêm chỉnh chấp hành Hiến pháp và pháp luật.", "Tòa án được quyền xét xử theo cảm tính nếu chưa có quy định.", "Địa phương được đặt ra quy định riêng trái với văn bản của Trung ương."], 1, "Pháp chế XHCN đòi hỏi mọi cơ quan nhà nước, tổ chức và mọi công dân đều phải nghiêm chỉnh chấp hành Hiến pháp và pháp luật."],
  [36, "p2", "Theo Hiến pháp 2013 (được sửa đổi, bổ sung năm 2025), cơ quan nào có quyền lập hiến và lập pháp?", ["Chính phủ.", "Quốc hội.", "Chủ tịch nước.", "Tòa án nhân dân tối cao."], 1, "Quốc hội là cơ quan đại biểu cao nhất của Nhân dân, cơ quan quyền lực nhà nước cao nhất, thực hiện quyền lập hiến, lập pháp."],
  [37, "p2", "Độ tuổi tối thiểu để công dân Việt Nam có quyền bầu cử đại biểu Quốc hội là bao nhiêu?", ["Đủ 16 tuổi.", "Đủ 18 tuổi.", "Đủ 20 tuổi.", "Đủ 21 tuổi."], 1, "Theo Điều 27 Hiến pháp 2013, công dân đủ 18 tuổi trở lên có quyền bầu cử và đủ 21 tuổi trở lên có quyền ứng cử."],
  [38, "p2", "Theo Hiến pháp 2013, ai là người đứng đầu Nhà nước, thay mặt nước Cộng hòa xã hội chủ nghĩa Việt Nam về đối nội và đối ngoại?", ["Thủ tướng Chính phủ.", "Chủ tịch Quốc hội.", "Chủ tịch nước.", "Tổng Bí thư."], 2, "Chủ tịch nước là người đứng đầu Nhà nước, thay mặt nước CHXHCN Việt Nam về đối nội và đối ngoại."],
  [39, "p2", "Theo Hiến pháp 2013, Chính phủ là cơ quan gì?", ["Cơ quan quyền lực nhà nước cao nhất.", "Cơ quan hành chính nhà nước cao nhất.", "Cơ quan xét xử.", "Cơ quan kiểm sát."], 1, "Chính phủ là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp và là cơ quan chấp hành của Quốc hội."],
  [40, "p2", "Quyền con người, quyền công dân chỉ có thể bị hạn chế theo quy định của:", ["Nghị định.", "Luật.", "Thông tư.", "Lệnh."], 1, "Theo Điều 14 Hiến pháp 2013, quyền con người, quyền công dân chỉ có thể bị hạn chế theo quy định của luật trong trường hợp cần thiết."],
  [41, "p2", "Theo Hiến pháp 2013, mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật:", ["Cho phép.", "Không cấm.", "Khuyến khích.", "Quy định cụ thể."], 1, "Điều 33 Hiến pháp 2013 quy định mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật không cấm."],
  [42, "p2", "Quốc hội họp thường kỳ mỗi năm mấy kỳ?", ["Một kỳ.", "Hai kỳ.", "Ba kỳ.", "Bất thường khi cần thiết."], 1, "Quốc hội họp thường kỳ mỗi năm 2 kỳ (và có thể họp bất thường khi cần thiết)."],
  [43, "p2", "Ai có thẩm quyền công bố Hiến pháp, luật, pháp lệnh?", ["Chủ tịch Quốc hội.", "Thủ tướng Chính phủ.", "Chủ tịch nước.", "Chánh án Tòa án nhân dân tối cao."], 2, "Chủ tịch nước có thẩm quyền công bố Hiến pháp, luật, pháp lệnh."],
  [44, "p2", "Tòa án nhân dân xét xử theo nguyên tắc nào?", ["Kịp thời, công bằng.", "Tập thể và quyết định theo đa số.", "Công khai, trừ trường hợp đặc biệt.", "Cả B và C."], 3, "Tòa án nhân dân xét xử công khai (trừ trường hợp đặc biệt) và xét xử tập thể, quyết định theo đa số (trừ thủ tục rút gọn)."],
  [45, "p2", "Nhiệm kỳ của Quốc hội là:", ["4 năm.", "5 năm.", "6 năm.", "Phụ thuộc vào từng khóa."], 1, "Nhiệm kỳ của mỗi khóa Quốc hội là 5 năm."],
  [46, "p2", "Theo Hiến pháp 2013, ai là Tổng tư lệnh lực lượng vũ trang nhân dân?", ["Thủ tướng Chính phủ.", "Bộ trưởng Bộ Quốc phòng.", "Chủ tịch nước.", "Tổng Bí thư."], 2, "Chủ tịch nước thống lĩnh lực lượng vũ trang nhân dân, giữ chức Chủ tịch Hội đồng quốc phòng và an ninh."],
  [47, "p2", "Quyền ứng cử của công dân được thực hiện khi họ đáp ứng đủ các tiêu chuẩn, điều kiện do ai quy định?", ["Ủy ban bầu cử.", "Pháp luật.", "Chính phủ.", "Mặt trận Tổ quốc Việt Nam."], 1, "Quyền ứng cử được thực hiện theo các tiêu chuẩn, điều kiện do pháp luật quy định."],
  [48, "p2", "Cơ quan nào có quyền giám sát tối cao đối với toàn bộ hoạt động của Nhà nước?", ["Chính phủ.", "Tòa án nhân dân tối cao.", "Viện kiểm sát nhân dân tối cao.", "Quốc hội."], 3, "Quốc hội thực hiện quyền giám sát tối cao đối với toàn bộ hoạt động của Nhà nước."],
  [49, "p2", "Theo Hiến pháp 2013, \"Nước Cộng hòa xã hội chủ nghĩa Việt Nam do ..... làm chủ\". Điền vào chỗ trống.", ["Đảng Cộng sản Việt Nam.", "Nhà nước.", "Nhân dân.", "Giai cấp công nhân."], 2, "Điều 2 Hiến pháp 2013: Nước Cộng hòa xã hội chủ nghĩa Việt Nam do Nhân dân làm chủ."],
  [50, "p2", "Ủy ban Thường vụ Quốc hội là:", ["Cơ quan chấp hành của Quốc hội.", "Cơ quan thường trực của Quốc hội.", "Cơ quan chuyên môn của Quốc hội.", "Một phiên họp của Quốc hội."], 1, "Ủy ban Thường vụ Quốc hội là cơ quan thường trực của Quốc hội."],
  [51, "p2", "Tòa án nhân dân và Viện kiểm sát nhân dân được tổ chức và hoạt động theo nguyên tắc:", ["Lãnh đạo tập thể, cá nhân phụ trách.", "Tập trung dân chủ.", "Độc lập và chỉ tuân theo pháp luật (đối với Tòa án).", "Cả B và C."], 3, "Hệ thống cơ quan tư pháp tuân theo nguyên tắc tập trung dân chủ; riêng khi xét xử, Thẩm phán và Hội thẩm độc lập và chỉ tuân theo pháp luật."],
  [52, "p2", "Mọi công dân đều bình đẳng trước pháp luật có nghĩa là:", ["Mọi người đều có quyền và nghĩa vụ như nhau.", "Mọi người đều được hưởng các phúc lợi như nhau.", "Mọi người không bị phân biệt đối xử trong đời sống chính trị, dân sự, kinh tế, văn hóa, xã hội.", "Mọi người đều phải chịu mức hình phạt như nhau cho cùng một tội."], 2, "Bình đẳng trước pháp luật nghĩa là không ai bị phân biệt đối xử trong đời sống chính trị, dân sự, kinh tế, văn hóa, xã hội."],
  [53, "p2", "\"Bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa là sự nghiệp của toàn dân\". Đây là:", ["Quyền của công dân.", "Nghĩa vụ của công dân.", "Cả quyền và nghĩa vụ thiêng liêng.", "Trách nhiệm của quân đội."], 2, "Điều 45 Hiến pháp 2013 khẳng định bảo vệ Tổ quốc là nghĩa vụ thiêng liêng và quyền cao quý của công dân."],
  [54, "p2", "Thủ tướng Chính phủ do cơ quan nào bầu?", ["Chính phủ.", "Quốc hội.", "Ban chấp hành Trung ương Đảng.", "Ủy ban thường vụ Quốc hội."], 1, "Thủ tướng Chính phủ do Quốc hội bầu trong số đại biểu Quốc hội theo đề nghị của Chủ tịch nước."],
  [55, "p2", "Hội đồng nhân dân là cơ quan:", ["Hành chính nhà nước ở địa phương.", "Quyền lực nhà nước ở địa phương.", "Xét xử ở địa phương.", "Chuyên môn của UBND."], 1, "Hội đồng nhân dân là cơ quan quyền lực nhà nước ở địa phương, đại diện cho ý chí, nguyện vọng và quyền làm chủ của Nhân dân."],
  [56, "p2", "Theo Hiến pháp sửa đổi, bổ sung năm 2025, đơn vị hành chính Việt Nam được tổ chức thành mấy cấp?", ["3 cấp (tỉnh, huyện, xã).", "2 cấp (cấp tỉnh và cấp xã/phường/đặc khu).", "4 cấp.", "Chỉ có cấp tỉnh."], 1, "Theo Hiến pháp sửa đổi, bổ sung năm 2025, đơn vị hành chính Việt Nam tổ chức theo mô hình 2 cấp: cấp tỉnh và cấp xã/phường/đặc khu."],
  [57, "p2", "Cơ quan nào có chức năng thực hành quyền công tố và kiểm sát hoạt động tư pháp?", ["Tòa án nhân dân.", "Chính phủ.", "Viện kiểm sát nhân dân.", "Thanh tra Chính phủ."], 2, "Viện kiểm sát nhân dân thực hành quyền công tố và kiểm sát hoạt động tư pháp."],
  [58, "p3", "Quyết định hành chính là:", ["Văn bản quy phạm pháp luật do cơ quan hành chính ban hành.", "Văn bản áp dụng pháp luật do cơ quan, người có thẩm quyền trong cơ quan hành chính nhà nước ban hành để giải quyết vụ việc cụ thể.", "Bản án của Tòa án hành chính.", "Kết luận của cơ quan thanh tra."], 1, "Quyết định hành chính là văn bản áp dụng pháp luật do cơ quan/người có thẩm quyền hành chính ban hành để giải quyết vụ việc cụ thể."],
  [59, "p3", "Vi phạm hành chính là:", ["Hành vi có lỗi do cá nhân, tổ chức thực hiện, vi phạm quy định của pháp luật về quản lý nhà nước.", "Hành vi nguy hiểm cho xã hội được quy định trong Bộ luật Hình sự.", "Hành vi vi phạm hợp đồng.", "Hành vi vi phạm kỷ luật."], 0, "Vi phạm hành chính là hành vi có lỗi vi phạm quy định quản lý nhà nước mà không phải là tội phạm và theo quy định phải bị xử phạt VPHC."],
  [60, "p3", "Khiếu nại là việc công dân, cơ quan, tổ chức đề nghị cơ quan, người có thẩm quyền xem xét lại:", ["Quyết định hành chính, hành vi hành chính.", "Bản án của Tòa án.", "Quy định của pháp luật.", "Hành vi của người khác."], 0, "Khiếu nại là việc đề nghị cơ quan, người có thẩm quyền xem xét lại quyết định hành chính hoặc hành vi hành chính khi có căn cứ cho rằng trái luật."],
  [61, "p3", "Hình thức xử phạt vi phạm hành chính nào sau đây là hình thức xử phạt chính?", ["Tước quyền sử dụng giấy phép.", "Tịch thu tang vật, phương tiện.", "Phạt tiền.", "Buộc khôi phục lại tình trạng ban đầu."], 2, "Cảnh cáo và Phạt tiền là hai hình thức xử phạt chính trong xử lý vi phạm hành chính."],
  [62, "p3", "Độ tuổi tối thiểu bị xử phạt vi phạm hành chính là:", ["Đủ 12 tuổi.", "Đủ 14 tuổi.", "Đủ 16 tuổi.", "Đủ 18 tuổi."], 1, "Người từ đủ 14 tuổi đến dưới 16 tuổi bị xử phạt VPHC về hành vi do cố ý; từ đủ 16 tuổi trở lên bị xử phạt về mọi VPHC."],
  [63, "p3", "Người có thẩm quyền xử phạt vi phạm hành chính thông thường là:", ["Chủ tịch UBND các cấp.", "Cảnh sát giao thông, Thanh tra viên đang thi hành công vụ.", "Chiến sĩ công an nhân dân.", "Tất cả các đối tượng trên tùy theo mức độ vi phạm."], 3, "Chủ tịch UBND các cấp, lực lượng Công an nhân dân, CSGT, Thanh tra viên... đều có thẩm quyền xử phạt theo phân cấp luật định."],
  [64, "p3", "Thời hiệu xử lý vi phạm hành chính thông thường là:", ["01 năm.", "02 năm.", "05 năm.", "06 tháng."], 0, "Thời hiệu xử phạt VPHC thông thường là 01 năm (một số lĩnh vực đặc thù như thuế, xây dựng, môi trường... là 02 năm)."],
  [65, "p3", "Trong xử phạt vi phạm hành chính, mức phạt tiền đối với tổ chức gấp bao nhiêu lần mức phạt tiền đối với cá nhân?", ["Bằng mức của cá nhân.", "Gấp 02 lần.", "Gấp 03 lần.", "Gấp 05 lần."], 1, "Cùng một hành vi vi phạm hành chính, mức phạt tiền đối với tổ chức bằng 02 lần mức phạt tiền đối với cá nhân."],
  [66, "p3", "Biện pháp \"Buộc khôi phục lại tình trạng ban đầu\" trong xử lý vi phạm hành chính thuộc nhóm nào?", ["Hình thức xử phạt chính.", "Hình thức xử phạt bổ sung.", "Biện pháp khắc phục hậu quả.", "Biện pháp ngăn chặn."], 2, "Buộc khôi phục lại tình trạng ban đầu là một trong các biện pháp khắc phục hậu quả theo Luật Xử lý VPHC."],
  [67, "p4", "Tội phạm là hành vi nguy hiểm cho xã hội được quy định trong:", ["Bộ luật Dân sự.", "Bộ luật Hình sự.", "Luật Xử lý vi phạm hành chính.", "Luật Khiếu nại."], 1, "Tội phạm là hành vi nguy hiểm cho xã hội được quy định trong Bộ luật Hình sự."],
  [68, "p4", "Người từ đủ bao nhiêu tuổi trở lên phải chịu trách nhiệm hình sự về mọi tội phạm?", ["14 tuổi.", "16 tuổi.", "18 tuổi.", "20 tuổi."], 1, "Theo Điều 12 BLHS 2015, người từ đủ 16 tuổi trở lên phải chịu trách nhiệm hình sự về mọi tội phạm (trừ quy định riêng)."],
  [69, "p4", "Hình phạt nào sau đây không phải là hình phạt chính?", ["Cảnh cáo.", "Phạt tiền.", "Tù có thời hạn.", "Quản chế."], 3, "Quản chế là hình phạt bổ sung (không phải hình phạt chính)."],
  [70, "p4", "Phòng vệ chính đáng là:", ["Hành vi gây thiệt hại cho người khác.", "Hành vi chống trả một cách cần thiết người đang có hành vi xâm phạm lợi ích của Nhà nước, của tổ chức, của mình hoặc của người khác.", "Hành vi gây thiệt hại để tránh một nguy cơ đang thực tế đe dọa.", "Hành vi tự ý nửa chừng chấm dứt việc phạm tội."], 1, "Phòng vệ chính đáng là hành vi chống trả một cách cần thiết người đang có hành vi xâm phạm lợi ích hợp pháp của Nhà nước, tổ chức, cá nhân."],
  [71, "p4", "Đồng phạm là trường hợp:", ["Một người thực hiện tội phạm.", "Có từ hai người trở lên cố ý cùng thực hiện một tội phạm.", "Nhiều người vô ý phạm tội.", "Một người giúp sức cho người khác phạm tội."], 1, "Đồng phạm là trường hợp có từ hai người trở lên cố ý cùng thực hiện một tội phạm."],
  [72, "p4", "Tình trạng không có năng lực trách nhiệm hình sự là tình trạng một người thực hiện hành vi nguy hiểm cho xã hội trong khi:", ["Đang bị say rượu.", "Đang mắc một bệnh làm mất khả năng nhận thức hoặc khả năng điều khiển hành vi.", "Dưới 16 tuổi.", "Bị người khác ép buộc."], 1, "Người đang mắc bệnh tâm thần hoặc bệnh khác làm mất khả năng nhận thức hoặc điều khiển hành vi thì không phải chịu TNHS."],
  [73, "p4", "Mục đích của hình phạt không bao gồm:", ["Trừng trị người phạm tội.", "Giáo dục, cải tạo người phạm tội.", "Trả thù người phạm tội.", "Răn đe, phòng ngừa tội phạm."], 2, "Hình phạt nhằm trừng trị, giáo dục, cải tạo người phạm tội và phòng ngừa chung, không nhằm mục đích trả thù."],
  [74, "p4", "Che giấu tội phạm là hành vi:", ["Hứa hẹn trước với người phạm tội sẽ che giấu.", "Không hứa hẹn trước nhưng sau khi tội phạm được thực hiện đã che giấu người phạm tội, dấu vết, tang vật của tội phạm.", "Biết tội phạm đang được chuẩn bị, đang được thực hiện hoặc đã được thực hiện mà không tố giác.", "Xúi giục người khác phạm tội."], 1, "Che giấu tội phạm là hành vi không hứa hẹn trước nhưng sau khi tội phạm xảy ra đã che giấu người phạm tội, dấu vết, tang vật."],
  [75, "p4", "Tuổi chịu trách nhiệm hình sự được tính:", ["Theo ngày, tháng, năm sinh dương lịch.", "Theo ngày, tháng, năm sinh âm lịch.", "Tính theo năm hành chính.", "Tùy theo từng loại tội phạm."], 0, "Tuổi chịu trách nhiệm hình sự được tính theo ngày, tháng, năm sinh dương lịch."],
  [76, "p4", "Tội phạm hoàn thành khi nào?", ["Khi người phạm tội bắt đầu thực hiện hành vi phạm tội.", "Khi hành vi phạm tội đã thỏa mãn hết các dấu hiệu trong cấu thành tội phạm.", "Khi hậu quả vật chất của tội phạm xảy ra.", "Khi người phạm tội tự ý nửa chừng chấm dứt việc phạm tội."], 1, "Tội phạm hoàn thành khi hành vi đã thỏa mãn đầy đủ các dấu hiệu của cấu thành tội phạm tương ứng."],
  [77, "p4", "Không tố giác tội phạm có phải là hành vi phạm tội không?", ["Không, đó là quyền của công dân.", "Có, trong những trường hợp do Bộ luật Hình sự quy định.", "Luôn luôn là tội phạm đối với mọi hành vi vi phạm pháp luật.", "Chỉ là vi phạm đạo đức."], 1, "Không tố giác tội phạm là tội phạm trong các trường hợp luật định (Điều 390 BLHS)."],
  [78, "p4", "Chuẩn bị phạm tội là:", ["Tìm kiếm, sửa soạn công cụ, phương tiện phạm tội.", "Thành lập, tham gia nhóm tội phạm.", "Các hành vi tạo ra những điều kiện cần thiết cho việc thực hiện tội phạm.", "Cả A, B và C."], 3, "Chuẩn bị phạm tội bao gồm tìm kiếm, sửa soạn công cụ, phương tiện, thành lập/tham gia nhóm tội phạm hoặc tạo điều kiện cần thiết khác."],
  [79, "p4", "Loại tội phạm nào có tính nguy hiểm cho xã hội cao nhất?", ["Tội phạm ít nghiêm trọng.", "Tội phạm nghiêm trọng.", "Tội phạm rất nghiêm trọng.", "Tội phạm đặc biệt nghiêm trọng."], 3, "Bốn loại tội phạm theo mức độ tăng dần: ít nghiêm trọng → nghiêm trọng → rất nghiêm trọng → đặc biệt nghiêm trọng."],
  [80, "p4", "Tình thế cấp thiết là tình thế của người vì muốn tránh một nguy cơ đang thực tế đe dọa lợi ích của Nhà nước, của tổ chức, quyền, lợi ích chính đáng của mình hoặc của người khác mà không còn cách nào khác là:", ["Chống trả lại một cách cần thiết người đang xâm phạm.", "Gây một thiệt hại nhỏ hơn thiệt hại cần ngăn ngừa.", "Tự ý nửa chừng chấm dứt việc phạm tội.", "Chấp nhận rủi ro trong kinh doanh."], 1, "Trong tình thế cấp thiết, chủ thể không còn cách nào khác buộc phải gây thiệt hại nhỏ hơn thiệt hại cần ngăn ngừa."],
  [81, "p4", "Một người thực hiện nhiều hành vi phạm tội, chưa bị xét xử lần nào thì Tòa án xét xử theo nguyên tắc nào?", ["Tổng hợp hình phạt.", "Xét xử từng tội và quyết định hình phạt cho từng tội, sau đó tổng hợp hình phạt.", "Chỉ xét xử tội nặng nhất.", "Miễn hình phạt cho các tội nhẹ hơn."], 1, "Khi phạm nhiều tội chưa bị xét xử, Tòa án xét xử từng tội, quyết định hình phạt cho từng tội rồi tổng hợp hình phạt chung."],
  [82, "p4", "Miễn trách nhiệm hình sự có nghĩa là:", ["Không bị coi là có tội.", "Có tội nhưng được miễn hình phạt.", "Có tội nhưng được miễn không phải chịu trách nhiệm hình sự theo quy định của luật.", "Không bao giờ bị điều tra."], 2, "Miễn TNHS là người có hành vi phạm tội nhưng theo quy định của BLHS được miễn không phải chịu trách nhiệm hình sự."],
  [83, "p4", "Tự ý nửa chừng chấm dứt việc phạm tội được miễn trách nhiệm hình sự về:", ["Tội định phạm.", "Mọi tội phạm.", "Tội đã thực hiện khi hành vi thực tế đã đủ yếu tố cấu thành một tội phạm khác.", "Mọi hành vi gây thiệt hại trước đó."], 0, "Người tự ý nửa chừng chấm dứt việc phạm tội được miễn TNHS về tội định phạm (nếu hành vi thực tế cấu thành tội khác thì chịu TNHS về tội đó)."],
  [84, "p4", "Người thực hành trong vụ án đồng phạm là người:", ["Khởi xướng, chủ mưu, cầm đầu.", "Tạo điều kiện tinh thần hoặc vật chất cho việc thực hiện tội phạm.", "Trực tiếp thực hiện tội phạm.", "Hứa hẹn che giấu người phạm tội."], 2, "Người thực hành là người trực tiếp thực hiện tội phạm."],
  [85, "p4", "Lỗi vô ý vì quá tự tin là trường hợp người phạm tội:", ["Không thấy trước hành vi của mình có thể gây ra hậu quả nguy hại.", "Thấy trước hành vi của mình có thể gây ra hậu quả nguy hại, nhưng cho rằng hậu quả đó sẽ không xảy ra hoặc có thể ngăn ngừa được.", "Nhận thức rõ hành vi của mình là nguy hiểm nhưng vẫn thực hiện.", "Mong muốn hậu quả xảy ra."], 1, "Lỗi vô ý vì quá tự tin: thấy trước khả năng gây hậu quả nguy hại nhưng tin rằng hậu quả sẽ không xảy ra hoặc có thể ngăn ngừa được."],
  [86, "p4", "Hình phạt tử hình không áp dụng đối với:", ["Người dưới 18 tuổi khi phạm tội.", "Phụ nữ có thai, phụ nữ đang nuôi con dưới 36 tháng tuổi.", "Người đủ 75 tuổi trở lên khi phạm tội hoặc khi xét xử.", "Cả A, B và C."], 3, "Không áp dụng tử hình đối với người dưới 18 tuổi khi phạm tội, phụ nữ có thai/nuôi con dưới 36 tháng tuổi và người đủ 75 tuổi trở lên."],
  [87, "p4", "Thời hiệu truy cứu trách nhiệm hình sự là:", ["Thời hạn do Bộ luật Hình sự quy định mà khi hết thời hạn đó thì người phạm tội không bị truy cứu trách nhiệm hình sự.", "Thời hạn để người phạm tội kháng cáo.", "Thời hạn chấp hành hình phạt.", "Thời hạn để Tòa án đưa vụ án ra xét xử."], 0, "Thời hiệu truy cứu TNHS là thời hạn luật định mà khi hết thời hạn đó người phạm tội không bị truy cứu TNHS."],
  [88, "p4", "Hành vi nào sau đây là phạm tội chưa đạt?", ["A chuẩn bị dao để đi giết B.", "A đâm B nhưng B không chết do nguyên nhân ngoài ý muốn của A.", "A đang đi thì tự nguyện từ bỏ ý định giết B.", "A che giấu cho B sau khi B phạm tội."], 1, "Phạm tội chưa đạt là cố ý thực hiện tội phạm nhưng không thực hiện được đến cùng vì những nguyên nhân ngoài ý muốn."],
  [89, "p4", "Các giai đoạn thực hiện tội phạm cố ý bao gồm:", ["Chuẩn bị phạm tội, phạm tội chưa đạt, tội phạm hoàn thành.", "Lên kế hoạch, thực hiện, che giấu.", "Cố ý trực tiếp, cố ý gián tiếp.", "Đồng phạm, phạm tội một mình."], 0, "Ba giai đoạn thực hiện tội phạm cố ý: chuẩn bị phạm tội, phạm tội chưa đạt và tội phạm hoàn thành."],
  [90, "p4", "Phạt tiền là hình phạt được áp dụng với:", ["Chỉ pháp nhân thương mại.", "Chỉ cá nhân.", "Cả cá nhân và pháp nhân thương mại phạm tội.", "Mọi tổ chức."], 2, "Theo BLHS 2015, phạt tiền được áp dụng đối với cả cá nhân và pháp nhân thương mại phạm tội."],
  [91, "p4", "Cơ quan nào có thẩm quyền khởi tố vụ án hình sự?", ["Chỉ có Cơ quan điều tra.", "Chỉ có Viện kiểm sát.", "Cơ quan điều tra, Viện kiểm sát và một số cơ quan khác được giao nhiệm vụ tiến hành một số hoạt động điều tra.", "Chỉ có Tòa án."], 2, "Cơ quan điều tra, Viện kiểm sát và cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra có thẩm quyền khởi tố vụ án hình sự."],
  [92, "p4", "Nguyên tắc \"không ai bị coi là có tội khi chưa có bản án kết tội của Tòa án đã có hiệu lực pháp luật\" là:", ["Nguyên tắc pháp chế.", "Nguyên tắc suy đoán vô tội.", "Nguyên tắc bình đẳng trước pháp luật.", "Nguyên tắc xét xử công khai."], 1, "Đây là nội dung cốt lõi của nguyên tắc suy đoán vô tội (Điều 13 BLTTHS)."],
  [93, "p4", "Ai có quyền bào chữa cho người bị buộc tội?", ["Chỉ có Luật sư.", "Người bị buộc tội tự bào chữa.", "Người đại diện của người bị buộc tội.", "Tất cả các phương án trên (cùng bào chữa viên nhân dân theo luật định)."], 3, "Người bị buộc tội có quyền tự bào chữa hoặc nhờ luật sư, người đại diện, bào chữa viên nhân dân bào chữa."],
  [94, "p4", "Biện pháp ngăn chặn nào nghiêm khắc nhất?", ["Giữ người trong trường hợp khẩn cấp.", "Bắt người bị giữ trong trường hợp khẩn cấp.", "Tạm giam.", "Cấm đi khỏi nơi cư trú."], 2, "Tạm giam là biện pháp ngăn chặn nghiêm khắc nhất trong tố tụng hình sự."],
  [95, "p4", "Hội đồng xét xử sơ thẩm vụ án hình sự gồm:", ["Một Thẩm phán và hai Hội thẩm nhân dân.", "Hai Thẩm phán và một Hội thẩm nhân dân.", "Ba Thẩm phán.", "Tùy từng vụ án, có thể là một Thẩm phán và hai Hội thẩm hoặc hai Thẩm phán và ba Hội thẩm."], 3, "HĐXX sơ thẩm thông thường gồm 1 Thẩm phán và 2 Hội thẩm; vụ án nghiêm trọng, phức tạp có thể gồm 2 Thẩm phán và 3 Hội thẩm."],
  [96, "p4", "Thời hạn điều tra vụ án hình sự đối với tội ít nghiêm trọng không quá:", ["01 tháng.", "02 tháng.", "03 tháng.", "04 tháng."], 1, "Thời hạn điều tra đối với tội phạm ít nghiêm trọng không quá 02 tháng."],
  [97, "p4", "Nhiệm vụ của Luật Tố tụng hình sự là:", ["Phát hiện chính xác, nhanh chóng và xử lý công minh mọi hành vi phạm tội.", "Bảo vệ quyền con người, quyền công dân.", "Giáo dục mọi người ý thức tuân theo pháp luật.", "Cả A, B và C."], 3, "Luật Tố tụng hình sự nhằm phát hiện, xử lý công minh tội phạm, bảo vệ quyền con người và giáo dục ý thức tuân thủ pháp luật."],
  [98, "p4", "Chứng cứ trong vụ án hình sự là:", ["Lời khai của bị can.", "Lời khai của người làm chứng.", "Vật chứng.", "Những gì có thật, được thu thập theo trình tự, thủ tục do Bộ luật Tố tụng hình sự quy định."], 3, "Chứng cứ là những gì có thật, được thu thập theo trình tự, thủ tục do BLTTHS quy định để xác định sự thật vụ án."],
  [99, "p4", "Tòa án xét xử sơ thẩm vụ án hình sự bằng một bản án nhân danh:", ["Tòa án nhân dân tối cao.", "Nước Cộng hòa Xã hội Chủ nghĩa Việt Nam.", "Quốc hội.", "Chính phủ."], 1, "Tòa án xét xử và ra bản án nhân danh Nước Cộng hòa Xã hội Chủ nghĩa Việt Nam."],
  [100, "p4", "Cơ quan nào có quyền ra quyết định truy tố bị can trước Tòa án?", ["Cơ quan điều tra.", "Tòa án.", "Viện kiểm sát.", "Luật sư."], 2, "Viện kiểm sát có quyền ra quyết định truy tố bị can trước Tòa án bằng bản cáo trạng."],
  [101, "p4", "Bị cáo là người:", ["Bị khởi tố về hình sự.", "Đã bị Viện kiểm sát truy tố.", "Đã bị Tòa án quyết định đưa ra xét xử.", "Đã bị kết án."], 2, "Bị cáo là người hoặc pháp nhân đã bị Tòa án quyết định đưa ra xét xử."],
  [102, "p4", "Nguyên tắc nào đảm bảo mọi phán quyết của Tòa án phải dựa trên kết quả tranh tụng tại phiên tòa?", ["Nguyên tắc suy đoán vô tội.", "Nguyên tắc tranh tụng trong xét xử được bảo đảm.", "Nguyên tắc xét xử công khai.", "Nguyên tắc độc lập của Thẩm phán."], 1, "Nguyên tắc tranh tụng trong xét xử được bảo đảm yêu cầu phán quyết của Tòa án phải căn cứ vào kết quả tranh tụng tại phiên tòa."],
  [103, "p4", "Bắt người trong trường hợp khẩn cấp được tiến hành khi:", ["Có đủ căn cứ để xác định một người đang chuẩn bị thực hiện tội phạm rất nghiêm trọng hoặc đặc biệt nghiêm trọng.", "Có người chính mắt trông thấy và xác nhận đúng là người đã thực hiện tội phạm mà xét thấy cần bắt ngay.", "Tại người hoặc tại chỗ ở của người bị nghi thực hiện tội phạm có dấu vết của tội phạm.", "Cả A, B và C."], 3, "Cả ba trường hợp A, B, C đều là căn cứ giữ/bắt người trong trường hợp khẩn cấp theo BLTTHS."],
  [104, "p4", "Ai có quyền kháng cáo bản án, quyết định sơ thẩm hình sự?", ["Bị cáo, bị hại, người có quyền lợi, nghĩa vụ liên quan.", "Nguyên đơn dân sự, bị đơn dân sự, người bảo vệ quyền và lợi ích hợp pháp của họ.", "Người bào chữa.", "Cả A, B và C."], 3, "Bị cáo, bị hại, đương sự, người đại diện, người bào chữa (trong phạm vi luật định)... đều có quyền kháng cáo bản án sơ thẩm."],
  [105, "p4", "Kiểm sát viên là người được bổ nhiệm để thực hiện chức năng:", ["Xét xử.", "Điều tra.", "Thực hành quyền công tố và kiểm sát hoạt động tư pháp.", "Bào chữa."], 2, "Kiểm sát viên được bổ nhiệm để thực hành quyền công tố và kiểm sát hoạt động tư pháp."],
  [106, "p4", "Theo Bộ luật Tố tụng hình sự (sửa đổi, bổ sung năm 2025), hồ sơ vụ án hình sự có thể được lập dưới hình thức nào?", ["Chỉ lập bằng văn bản giấy.", "Chỉ lập bằng hồ sơ điện tử.", "Bằng văn bản giấy hoặc số hóa, sử dụng chữ ký số theo quy định.", "Chỉ ghi âm, ghi hình."], 2, "Theo BLTTHS sửa đổi, bổ sung năm 2025, hồ sơ vụ án hình sự có thể lập bằng văn bản giấy hoặc số hóa, sử dụng chữ ký số."],
  [107, "p4", "Người từ đủ bao nhiêu tuổi đến dưới bao nhiêu tuổi phải chịu trách nhiệm hình sự về tội phạm rất nghiêm trọng do cố ý hoặc tội phạm đặc biệt nghiêm trọng?", ["Từ đủ 12 tuổi đến dưới 14 tuổi.", "Từ đủ 14 tuổi đến dưới 16 tuổi.", "Từ đủ 16 tuổi đến dưới 18 tuổi.", "Từ đủ 18 tuổi đến dưới 20 tuổi."], 1, "Người từ đủ 14 tuổi đến dưới 16 tuổi chịu TNHS về tội rất nghiêm trọng do cố ý hoặc đặc biệt nghiêm trọng (các tội danh liệt kê tại Điều 12 BLHS)."],
  [108, "p5", "Năng lực hành vi dân sự đầy đủ của cá nhân có từ khi nào?", ["Khi sinh ra.", "Đủ 6 tuổi.", "Đủ 15 tuổi.", "Đủ 18 tuổi."], 3, "Người thành niên (từ đủ 18 tuổi trở lên) có năng lực hành vi dân sự đầy đủ, trừ trường hợp bị Tòa án tuyên mất/hạn chế/khó khăn nhận thức."],
  [109, "p5", "Giao dịch dân sự không tuân thủ quy định về hình thức thì bị vô hiệu khi:", ["Gây thiệt hại cho người khác.", "Pháp luật có quy định hình thức là điều kiện có hiệu lực của giao dịch.", "Một bên yêu cầu hủy bỏ.", "Giao dịch do người chưa thành niên thực hiện."], 1, "Giao dịch dân sự vi phạm quy định điều kiện có hiệu lực về hình thức thì vô hiệu (trừ các ngoại lệ đã thực hiện ít nhất 2/3 nghĩa vụ theo Điều 129 BLDS)."],
  [110, "p5", "Thời hiệu khởi kiện về hợp đồng là bao lâu?", ["01 năm.", "02 năm.", "03 năm.", "05 năm."], 2, "Theo Điều 429 BLDS 2015, thời hiệu khởi kiện yêu cầu Tòa án giải quyết tranh chấp hợp đồng là 03 năm."],
  [111, "p5", "Đối tượng nào sau đây không phải là tài sản theo quy định của Bộ luật Dân sự?", ["Vật.", "Tiền.", "Sức khỏe con người.", "Quyền tài sản."], 2, "Tài sản gồm vật, tiền, giấy tờ có giá và quyền tài sản; sức khỏe là quyền nhân thân, không phải tài sản."],
  [112, "p5", "Thừa kế theo pháp luật được áp dụng trong trường hợp nào?", ["Không có di chúc.", "Di chúc không hợp pháp.", "Những người thừa kế theo di chúc đều chết trước hoặc chết cùng thời điểm với người lập di chúc.", "Cả A, B và C."], 3, "Thừa kế theo pháp luật áp dụng khi không có di chúc, di chúc không hợp pháp hoặc người thừa kế theo di chúc chết trước/cùng thời điểm người lập di chúc."],
  [113, "p5", "Hàng thừa kế thứ nhất bao gồm:", ["Vợ, chồng, cha đẻ, mẹ đẻ, cha nuôi, mẹ nuôi, con đẻ, con nuôi của người chết.", "Ông nội, bà nội, ông ngoại, bà ngoại, anh ruột, chị ruột, em ruột của người chết.", "Cụ nội, cụ ngoại, bác ruột, chú ruột, cậu ruột, cô ruột, dì ruột của người chết.", "Cháu ruột, chắt ruột của người chết."], 0, "Hàng thừa kế thứ nhất gồm: vợ, chồng, cha đẻ, mẹ đẻ, cha nuôi, mẹ nuôi, con đẻ, con nuôi của người chết."],
  [114, "p5", "Pháp nhân là một tổ chức:", ["Được thành lập hợp pháp.", "Có cơ cấu tổ chức chặt chẽ.", "Có tài sản độc lập và tự chịu trách nhiệm bằng tài sản đó; nhân danh mình tham gia các quan hệ pháp luật.", "Cả A, B và C."], 3, "Một tổ chức có tư cách pháp nhân khi đáp ứng đủ 4 điều kiện tại Điều 74 BLDS 2015 (gồm cả A, B, C)."],
  [115, "p5", "Bồi thường thiệt hại ngoài hợp đồng phát sinh khi nào?", ["Có hành vi vi phạm hợp đồng.", "Có hành vi trái pháp luật xâm phạm đến tính mạng, sức khỏe, danh dự, tài sản của người khác.", "Khi các bên có thỏa thuận.", "Khi có yêu cầu của người làm chứng."], 1, "Bồi thường thiệt hại ngoài hợp đồng phát sinh khi có hành vi trái pháp luật xâm phạm tính mạng, sức khỏe, danh dự, tài sản... gây thiệt hại."],
  [116, "p5", "Hình thức của di chúc bao gồm:", ["Chỉ có hình thức di chúc bằng văn bản.", "Chỉ có hình thức di chúc miệng.", "Di chúc bằng văn bản và di chúc miệng.", "Di chúc bằng văn bản có người làm chứng và không có người làm chứng."], 2, "Di chúc có hai hình thức là di chúc bằng văn bản và di chúc miệng."],
  [117, "p5", "Giao dịch dân sự được xác lập bởi người chưa thành niên (từ đủ 6 đến chưa đủ 15 tuổi) thì cần có:", ["Sự đồng ý của người đại diện theo pháp luật, trừ giao dịch phục vụ nhu cầu sinh hoạt hằng ngày.", "Sự cho phép của Tòa án.", "Sự làm chứng của ít nhất 2 người.", "Sự đồng ý của Ủy ban nhân dân."], 0, "Người từ đủ 6 đến chưa đủ 15 tuổi khi xác lập giao dịch dân sự phải được người đại diện theo pháp luật đồng ý, trừ giao dịch phục vụ nhu cầu sinh hoạt hằng ngày."],
  [118, "p5", "Thời hiệu yêu cầu chia di sản thừa kế là bao lâu?", ["10 năm đối với bất động sản, 30 năm đối với động sản.", "30 năm đối với bất động sản, 10 năm đối với động sản.", "20 năm đối với mọi loại tài sản.", "Không có thời hiệu."], 1, "Điều 623 BLDS 2015: Thời hiệu yêu cầu chia di sản thừa kế là 30 năm đối với bất động sản và 10 năm đối với động sản."],
  [119, "p5", "Hợp đồng vô hiệu không làm phát sinh, thay đổi, chấm dứt quyền, nghĩa vụ dân sự của các bên kể từ thời điểm:", ["Giao dịch được xác lập.", "Tòa án tuyên vô hiệu.", "Các bên phát hiện ra sự vô hiệu.", "Một trong các bên yêu cầu."], 0, "Giao dịch dân sự vô hiệu không làm phát sinh, thay đổi, chấm dứt quyền và nghĩa vụ dân sự kể từ thời điểm giao dịch được xác lập."],
  [120, "p5", "Cá nhân bị Tòa án tuyên bố mất tích khi:", ["Biệt tích 6 tháng liền.", "Biệt tích 1 năm liền.", "Biệt tích 2 năm liền trở lên và đã áp dụng đầy đủ các biện pháp thông báo, tìm kiếm.", "Biệt tích 5 năm liền."], 2, "Cá nhân biệt tích 02 năm liền trở lên dù đã áp dụng đầy đủ biện pháp thông báo, tìm kiếm thì có thể bị Tòa án tuyên bố mất tích."],
  [121, "p5", "Quyền nào sau đây không thuộc quyền nhân thân?", ["Quyền đối với họ, tên.", "Quyền được bảo vệ danh dự, nhân phẩm, uy tín.", "Quyền sở hữu nhà ở.", "Quyền xác định lại giới tính."], 2, "Quyền sở hữu nhà ở là quyền tài sản, không phải quyền nhân thân."],
  [122, "p5", "Người thừa kế không phụ thuộc vào nội dung của di chúc được hưởng phần di sản bằng:", ["Một nửa suất của một người thừa kế theo pháp luật.", "Toàn bộ suất của một người thừa kế theo pháp luật.", "Hai phần ba suất của một người thừa kế theo pháp luật.", "Tùy theo quyết định của Tòa án."], 2, "Người thừa kế không phụ thuộc nội dung di chúc được hưởng phần di sản bằng 2/3 suất của một người thừa kế theo pháp luật."],
  [123, "p5", "Trách nhiệm bồi thường thiệt hại do nguồn nguy hiểm cao độ gây ra là trách nhiệm:", ["Dân sự theo hợp đồng.", "Dân sự ngoài hợp đồng.", "Hình sự.", "Hành chính."], 1, "Trách nhiệm bồi thường thiệt hại do nguồn nguy hiểm cao độ gây ra là trách nhiệm dân sự ngoài hợp đồng."],
  [124, "p5", "Khi bên có nghĩa vụ chậm thực hiện nghĩa vụ thì phải chịu:", ["Lãi trên số tiền chậm trả.", "Bồi thường thiệt hại nếu có.", "Trách nhiệm dân sự do chậm thực hiện nghĩa vụ.", "Cả A và B."], 3, "Khi chậm thực hiện nghĩa vụ trả tiền/nghĩa vụ dân sự, bên vi phạm phải trả lãi chậm trả và bồi thường thiệt hại nếu có."],
  [125, "p5", "Hợp đồng tặng cho tài sản là hợp đồng:", ["Có đền bù.", "Không có đền bù.", "Song vụ.", "Luôn có điều kiện."], 1, "Hợp đồng tặng cho tài sản là hợp đồng không có đền bù (bên nhận không phải trả lợi ích vật chất tương ứng)."],
  [126, "p5", "Di sản thừa kế bao gồm:", ["Chỉ có tài sản riêng của người chết.", "Phần tài sản của người chết trong khối tài sản chung với người khác.", "Chỉ có quyền tài sản.", "Cả A và B."], 3, "Điều 612 BLDS 2015: Di sản bao gồm tài sản riêng của người chết và phần tài sản của người chết trong tài sản chung với người khác."],
  [127, "p5", "Cá nhân đủ điều kiện nào sau đây được lập di chúc mà không cần sự đồng ý của người khác?", ["Người thành niên minh mẫn, sáng suốt, không bị lừa dối, đe dọa, cưỡng ép.", "Người từ đủ 15 tuổi đến chưa đủ 18 tuổi.", "Người đang bị mất năng lực hành vi dân sự.", "Người đang bị Tòa án tuyên bố hạn chế năng lực hành vi dân sự."], 0, "Người thành niên minh mẫn, sáng suốt, không bị lừa dối, đe dọa, cưỡng ép có quyền tự lập di chúc."],
  [128, "p5", "Chủ sở hữu có quyền đòi lại tài sản từ người chiếm hữu, sử dụng tài sản không có căn cứ pháp luật thông qua:", ["Kiện đòi lại tài sản.", "Kiện yêu cầu bồi thường thiệt hại.", "Kiện yêu cầu chấm dứt hành vi cản trở.", "Cả A, B và C."], 0, "Theo Điều 166 BLDS 2015, chủ sở hữu có quyền đòi lại tài sản từ người chiếm hữu không có căn cứ pháp luật thông qua kiện đòi lại tài sản."],
  [129, "p5", "Quyền sở hữu bao gồm những quyền năng nào?", ["Quyền chiếm hữu.", "Quyền sử dụng.", "Quyền định đoạt.", "Cả ba quyền trên."], 3, "Quyền sở hữu bao gồm 3 quyền năng: quyền chiếm hữu, quyền sử dụng và quyền định đoạt."],
  [130, "p5", "Hợp đồng dân sự là:", ["Sự thỏa thuận của một bên.", "Sự thỏa thuận giữa các bên về việc xác lập, thay đổi hoặc chấm dứt quyền, nghĩa vụ dân sự.", "Cam kết của một bên.", "Giao dịch do một bên thực hiện."], 1, "Hợp đồng là sự thỏa thuận giữa các bên về việc xác lập, thay đổi hoặc chấm dứt quyền, nghĩa vụ dân sự."],
  [131, "p5", "Quyền nhân thân của cá nhân:", ["Có thể chuyển giao cho người khác.", "Không thể chuyển giao cho người khác, trừ trường hợp luật có quy định khác.", "Luôn gắn liền với tài sản.", "Do nhà nước quy định."], 1, "Quyền nhân thân gắn liền với mỗi cá nhân, không thể chuyển giao cho người khác, trừ trường hợp luật có quy định khác."],
  [132, "p5", "Cơ quan nào có thẩm quyền giải quyết các vụ án dân sự?", ["Ủy ban nhân dân.", "Tòa án nhân dân.", "Viện kiểm sát nhân dân.", "Cơ quan công an."], 1, "Tòa án nhân dân là cơ quan có thẩm quyền xét xử, giải quyết các vụ án dân sự."],
  [133, "p5", "Thời hạn chuẩn bị xét xử sơ thẩm đối với vụ án dân sự thông thường là:", ["01 tháng.", "02 tháng.", "04 tháng, trường hợp phức tạp có thể gia hạn nhưng không quá 02 tháng.", "06 tháng."], 2, "Thời hạn chuẩn bị xét xử sơ thẩm vụ án dân sự thông thường là 04 tháng; vụ án phức tạp có thể gia hạn thêm không quá 02 tháng."],
  [134, "p5", "Đương sự trong vụ án dân sự bao gồm:", ["Nguyên đơn, bị đơn.", "Người có quyền lợi, nghĩa vụ liên quan.", "Cả A và B.", "Người làm chứng, người giám định."], 2, "Đương sự trong vụ án dân sự gồm nguyên đơn, bị đơn và người có quyền lợi, nghĩa vụ liên quan."],
  [135, "p5", "Phiên tòa sơ thẩm dân sự chỉ được tiến hành khi:", ["Có mặt tất cả những người tham gia tố tụng.", "Có mặt nguyên đơn và bị đơn.", "Có đủ thành viên Hội đồng xét xử và Thư ký phiên tòa.", "Có mặt đại diện Viện kiểm sát."], 2, "Phiên tòa sơ thẩm dân sự chỉ được tiến hành khi có đủ thành viên Hội đồng xét xử và Thư ký phiên tòa."],
  [136, "p5", "Án phí dân sự sơ thẩm do ai chịu?", ["Nguyên đơn chịu.", "Bị đơn chịu.", "Đương sự phải chịu nếu yêu cầu của họ không được Tòa án chấp nhận (trừ trường hợp được miễn, giảm).", "Nhà nước chi trả toàn bộ."], 2, "Đương sự phải chịu án phí dân sự sơ thẩm nếu yêu cầu của họ không được Tòa án chấp nhận (trừ trường hợp được miễn, giảm)."],
  [137, "p5", "Theo quy định tố tụng dân sự hiện hành, hệ thống Tòa án nhân dân giải quyết vụ việc dân sự gồm các cấp nào?", ["Tòa án nhân dân cấp huyện và Tòa án nhân dân cấp tỉnh.", "Tòa án nhân dân cấp tỉnh và Tòa án nhân dân cấp cao.", "Tòa án nhân dân khu vực, Tòa án nhân dân cấp tỉnh, Tòa án nhân dân cấp cao và Tòa án nhân dân tối cao.", "Chỉ có Tòa án nhân dân khu vực."], 2, "Theo quy định tổ chức TAND hiện hành (sửa đổi 2025), hệ thống Tòa án gồm TAND khu vực, TAND cấp tỉnh, TAND cấp cao và TAND tối cao."],
  [138, "p5", "Xét xử phúc thẩm là việc:", ["Tòa án cấp trên trực tiếp xét xử lại vụ án mà bản án, quyết định của Tòa án cấp sơ thẩm chưa có hiệu lực pháp luật bị kháng cáo, kháng nghị.", "Xét xử lại vụ án đã có bản án hiệu lực pháp luật.", "Xét xử vụ án lần đầu tiên.", "Xem xét lại quyết định của Chánh án."], 0, "Xét xử phúc thẩm là việc Tòa án cấp trên trực tiếp xét xử lại bản án, quyết định sơ thẩm chưa có hiệu lực bị kháng cáo, kháng nghị."],
  [139, "p5", "Thủ tục giám đốc thẩm là để:", ["Xét xử lại vụ án sơ thẩm.", "Xét xử phúc thẩm vụ án.", "Xét lại bản án, quyết định của Tòa án đã có hiệu lực pháp luật nhưng bị kháng nghị vì có vi phạm pháp luật nghiêm trọng.", "Xét lại bản án do có tình tiết mới."], 2, "Giám đốc thẩm là xét lại bản án, quyết định đã có hiệu lực pháp luật bị kháng nghị do phát hiện vi phạm pháp luật nghiêm trọng."],
  [140, "p5", "Nguyên tắc hai cấp xét xử trong tố tụng dân sự có nghĩa là:", ["Vụ án được xét xử bởi hai Tòa án khác nhau.", "Bản án, quyết định của Tòa án cấp sơ thẩm có thể được Tòa án cấp trên trực tiếp xét xử lại theo trình tự phúc thẩm.", "Vụ án phải qua hai lần xét xử mới có hiệu lực.", "Đương sự có hai lần quyền kháng cáo."], 1, "Chế độ xét xử sơ thẩm, phúc thẩm bảo đảm bản án sơ thẩm có thể được Tòa án cấp trên trực tiếp xét xử lại theo trình tự phúc thẩm."],
  [141, "p5", "Hòa giải trong tố tụng dân sự là:", ["Bắt buộc đối với mọi vụ án.", "Một nguyên tắc, một thủ tục quan trọng nhằm giúp các đương sự thỏa thuận với nhau (trừ những vụ án không được hòa giải hoặc không hòa giải được).", "Do Thẩm phán tự quyết định.", "Chỉ tiến hành khi có yêu cầu của cả hai bên."], 1, "Hòa giải là nguyên tắc, thủ tục quan trọng giúp đương sự thỏa thuận giải quyết tranh chấp (trừ vụ án không được hoặc không hòa giải được)."],
  [142, "p5", "Ai có quyền kháng nghị theo thủ tục giám đốc thẩm, tái thẩm đối với bản án, quyết định đã có hiệu lực pháp luật của Tòa án?", ["Đương sự.", "Chánh án Tòa án nhân dân và Viện trưởng Viện kiểm sát nhân dân có thẩm quyền.", "Bất kỳ cá nhân, tổ chức nào.", "Luật sư."], 1, "Chỉ Chánh án TAND và Viện trưởng VKSND có thẩm quyền mới có quyền kháng nghị theo thủ tục giám đốc thẩm, tái thẩm."],
  [143, "p5", "Chi phí tố tụng trong vụ án dân sự bao gồm:", ["Án phí.", "Chi phí xem xét, thẩm định tại chỗ; chi phí định giá tài sản; chi phí giám định; chi phí cho người làm chứng, người phiên dịch...", "Lệ phí Tòa án.", "Chi phí thuê luật sư của đương sự."], 1, "Chi phí tố tụng gồm chi phí xem xét thẩm định tại chỗ, định giá tài sản, giám định, người làm chứng, phiên dịch..."],
  [144, "p5", "Tòa án ra quyết định đình chỉ giải quyết vụ án dân sự khi:", ["Nguyên đơn rút toàn bộ đơn khởi kiện (trong trường hợp không có yêu cầu phản tố, yêu cầu độc lập).", "Nguyên đơn đã được triệu tập hợp lệ lần thứ hai mà vẫn vắng mặt (không vì sự kiện bất khả kháng).", "Người khởi kiện không có quyền khởi kiện hoặc vụ án đã có bản án/quyết định đình chỉ có hiệu lực.", "Cả A, B và C."], 3, "Cả 3 trường hợp A, B, C đều là căn cứ để Tòa án ra quyết định đình chỉ giải quyết vụ án dân sự theo Điều 217 BLTTDS."],
  [145, "p5", "Cung cấp chứng cứ và chứng minh trong tố tụng dân sự là nghĩa vụ của ai?", ["Tòa án.", "Viện kiểm sát.", "Đương sự.", "Người làm chứng."], 2, "Theo Điều 6 BLTTDS, đương sự có quyền và nghĩa vụ cung cấp tài liệu, chứng cứ để chứng minh yêu cầu của mình."],
  [146, "p5", "Bản án phúc thẩm có hiệu lực pháp luật kể từ khi nào?", ["Sau 15 ngày kể từ ngày tuyên án.", "Sau 30 ngày kể từ ngày tuyên án.", "Kể từ ngày tuyên án.", "Khi được Chánh án ký."], 2, "Bản án phúc thẩm có hiệu lực pháp luật kể từ ngày tuyên án."],
  [147, "p5", "Ai có quyền kháng cáo bản án, quyết định sơ thẩm của Tòa án?", ["Chỉ có nguyên đơn.", "Chỉ có bị đơn.", "Đương sự, người đại diện hợp pháp của đương sự, cơ quan, tổ chức, cá nhân khởi kiện.", "Chỉ có Viện kiểm sát."], 2, "Đương sự, người đại diện hợp pháp của đương sự và cơ quan, tổ chức, cá nhân khởi kiện có quyền kháng cáo bản án sơ thẩm."],
  [148, "p5", "Thời hạn kháng cáo đối với bản án của Tòa án cấp sơ thẩm là bao nhiêu ngày kể từ ngày tuyên án?", ["07 ngày.", "15 ngày.", "20 ngày.", "30 ngày."], 1, "Thời hạn kháng cáo đối với bản án của Tòa án cấp sơ thẩm là 15 ngày kể từ ngày tuyên án."],
  [149, "p5", "Theo Bộ luật Tố tụng dân sự (sửa đổi, bổ sung năm 2025), Tòa án nhân dân cấp tỉnh có thẩm quyền phúc thẩm bản án, quyết định chưa có hiệu lực pháp luật của Tòa án nào?", ["Tòa án nhân dân cấp huyện.", "Tòa án nhân dân khu vực.", "Tòa án nhân dân cấp cao.", "Tòa án nhân dân tối cao."], 1, "Theo BLTTDS sửa đổi, bổ sung năm 2025, TAND cấp tỉnh xét xử phúc thẩm bản án, quyết định chưa có hiệu lực của TAND khu vực."],
  [150, "p6", "Độ tuổi kết hôn hợp pháp của nam giới ở Việt Nam là:", ["Từ đủ 18 tuổi trở lên.", "Từ đủ 19 tuổi trở lên.", "Từ đủ 20 tuổi trở lên.", "Từ đủ 22 tuổi trở lên."], 2, "Theo Điều 8 Luật HNGĐ 2014, nam từ đủ 20 tuổi trở lên mới đủ điều kiện kết hôn."],
  [151, "p6", "Độ tuổi kết hôn hợp pháp của nữ giới ở Việt Nam là:", ["Từ đủ 16 tuổi trở lên.", "Từ đủ 18 tuổi trở lên.", "Từ đủ 20 tuổi trở lên.", "Từ đủ 19 tuổi trở lên."], 1, "Nữ từ đủ 18 tuổi trở lên mới đủ điều kiện kết hôn theo Luật HNGĐ 2014."],
  [152, "p6", "Hành vi nào sau đây bị cấm trong hôn nhân và gia đình?", ["Kết hôn tự nguyện.", "Kết hôn giữa những người có họ trong phạm vi ba đời.", "Vợ chồng bình đẳng.", "Cha mẹ chăm sóc con cái."], 1, "Pháp luật cấm kết hôn giữa những người có họ trong phạm vi ba đời."],
  [153, "p6", "Tài sản nào sau đây là tài sản riêng của vợ, chồng?", ["Tiền lương, tiền công.", "Tài sản được thừa kế riêng trong thời kỳ hôn nhân.", "Thu nhập hợp pháp khác trong thời kỳ hôn nhân.", "Tài sản vợ chồng thỏa thuận là tài sản chung."], 1, "Tài sản được thừa kế riêng hoặc được tặng cho riêng trong thời kỳ hôn nhân là tài sản riêng của vợ, chồng."],
  [154, "p6", "Việc ly hôn do ai quyết định?", ["Tòa án nhân dân.", "Ủy ban nhân dân cấp xã.", "Hội phụ nữ.", "Hai bên vợ chồng tự thỏa thuận."], 0, "Tòa án nhân dân là cơ quan duy nhất có thẩm quyền giải quyết việc ly hôn."],
  [155, "p6", "Tòa án giải quyết cho ly hôn khi có căn cứ về việc:", ["Vợ chồng có mâu thuẫn.", "Một bên vợ hoặc chồng ngoại tình.", "Tình trạng trầm trọng, đời sống chung không thể kéo dài, mục đích của hôn nhân không đạt được.", "Vợ chồng sống ly thân 6 tháng."], 2, "Tòa án giải quyết ly hôn khi hôn nhân lâm vào tình trạng trầm trọng, đời sống chung không thể kéo dài, mục đích hôn nhân không đạt được."],
  [156, "p6", "Sau khi ly hôn, việc trông nom, chăm sóc, nuôi dưỡng con do ai quyết định?", ["Do cha quyết định.", "Do mẹ quyết định.", "Do vợ, chồng thỏa thuận; nếu không thỏa thuận được thì Tòa án quyết định.", "Do ông bà nội, ngoại quyết định."], 2, "Sau ly hôn, vợ chồng thỏa thuận người trực tiếp nuôi con; nếu không thỏa thuận được thì Tòa án quyết định căn cứ quyền lợi mọi mặt của con."],
  [157, "p6", "Chế độ tài sản của vợ chồng theo luật định là:", ["Chế độ tài sản riêng.", "Chế độ tài sản chung.", "Chế độ tài sản thỏa thuận.", "Chế độ tài sản cộng đồng tự động."], 1, "Chế độ tài sản của vợ chồng theo luật định xác lập chế độ tài sản chung trong thời kỳ hôn nhân (bên cạnh tài sản riêng luật định)."],
  [158, "p6", "Việc kết hôn phải được:", ["Cha mẹ hai bên đồng ý.", "Đăng ký tại cơ quan nhà nước có thẩm quyền.", "Tổ chức lễ cưới.", "Thông báo cho hàng xóm."], 1, "Việc kết hôn phải được đăng ký và do cơ quan nhà nước có thẩm quyền thực hiện mới có giá trị pháp lý."],
  [159, "p6", "Nghĩa vụ cấp dưỡng được đặt ra khi nào?", ["Giữa cha mẹ và con.", "Giữa anh, chị, em với nhau.", "Giữa vợ và chồng khi ly hôn.", "Cả A, B và C, nếu có các điều kiện theo luật định."], 3, "Nghĩa vụ cấp dưỡng đặt ra giữa cha mẹ và con, giữa anh chị em, giữa ông bà và cháu, giữa vợ và chồng khi ly hôn theo điều kiện luật định."],
  [160, "p6", "Mang thai hộ vì mục đích nhân đạo có được pháp luật Việt Nam cho phép không?", ["Không.", "Có, nhưng phải tuân theo các điều kiện nghiêm ngặt của pháp luật.", "Chỉ cho phép đối với người thân thích cùng dòng máu.", "Tùy từng trường hợp do vợ chồng thỏa thuận."], 1, "Luật HNGĐ 2014 cho phép mang thai hộ vì mục đích nhân đạo nhưng phải đáp ứng đầy đủ điều kiện nghiêm ngặt."],
  [161, "p6", "Vợ chồng có quyền và nghĩa vụ ngang nhau trong việc:", ["Lựa chọn nơi cư trú.", "Tôn trọng danh dự, nhân phẩm, uy tín của nhau.", "Cùng nhau xây dựng gia đình no ấm, bình đẳng.", "Cả A, B và C."], 3, "Vợ chồng bình đẳng, có quyền và nghĩa vụ ngang nhau trong mọi mặt của đời sống gia đình."],
  [162, "p6", "Cha dượng, mẹ kế có nghĩa vụ và quyền trông nom, nuôi dưỡng, chăm sóc, giáo dục con riêng của bên kia khi nào?", ["Trong mọi trường hợp.", "Khi cùng chung sống với con riêng.", "Khi cha đẻ, mẹ đẻ của đứa trẻ yêu cầu.", "Khi Tòa án quyết định."], 1, "Theo Điều 79 Luật HNGĐ 2014, cha dượng, mẹ kế có quyền và nghĩa vụ chăm sóc, nuôi dưỡng, giáo dục con riêng khi cùng chung sống."],
  [163, "p6", "Chồng không có quyền yêu cầu ly hôn trong trường hợp nào?", ["Vợ đang có thai.", "Vợ đang sinh con hoặc đang nuôi con dưới 12 tháng tuổi.", "Vợ đang đi công tác xa.", "Cả A và B."], 3, "Điều 51 Luật HNGĐ 2014: Chồng không có quyền yêu cầu ly hôn khi vợ đang có thai, sinh con hoặc đang nuôi con dưới 12 tháng tuổi."],
  [164, "p6", "Nợ chung của vợ chồng là khoản nợ:", ["Do một bên xác lập vì nhu cầu riêng.", "Phát sinh từ giao dịch do vợ chồng cùng thỏa thuận xác lập.", "Nghĩa vụ bồi thường thiệt hại mà theo quy định của pháp luật vợ chồng cùng phải chịu trách nhiệm.", "Cả B và C."], 3, "Nghĩa vụ chung về tài sản gồm giao dịch do vợ chồng cùng thỏa thuận xác lập và nghĩa vụ bồi thường thiệt hại mà pháp luật quy định vợ chồng cùng chịu trách nhiệm."],
  [165, "p6", "Việc xác định cha, mẹ cho con được thực hiện dựa trên nguyên tắc nào?", ["Suy đoán pháp lý (con sinh ra trong thời kỳ hôn nhân).", "Giám định gen (ADN).", "Sự thỏa thuận của các bên.", "Cả A, B và C (theo quy định của Luật Hôn nhân và Gia đình)."], 3, "Việc xác định cha, mẹ, con dựa trên suy đoán pháp lý trong thời kỳ hôn nhân, thỏa thuận nhận cha mẹ con hoặc chứng cứ khoa học (giám định ADN)."],
  [166, "p6", "Ly thân có làm chấm dứt quan hệ hôn nhân không?", ["Có.", "Không.", "Có, nếu ly thân trên 2 năm.", "Có, nếu có sự đồng ý của cả hai bên."], 1, "Pháp luật Việt Nam không quy định ly thân làm chấm dứt quan hệ hôn nhân; quan hệ hôn nhân chỉ chấm dứt khi có bản án/quyết định ly hôn có hiệu lực."],
  [167, "p6", "Khi chia tài sản chung của vợ chồng, Tòa án sẽ xem xét yếu tố nào?", ["Hoàn cảnh của gia đình và của vợ, chồng.", "Công sức đóng góp của vợ, chồng.", "Lỗi của mỗi bên trong vi phạm quyền, nghĩa vụ của vợ chồng.", "Cả A, B và C."], 3, "Khi chia tài sản chung, Tòa án xem xét hoàn cảnh gia đình, công sức đóng góp, lợi ích chính đáng và lỗi của mỗi bên."],
  [168, "p6", "Quan hệ giữa các thành viên khác trong gia đình (ông bà, cháu; anh chị em) chủ yếu được điều chỉnh bởi:", ["Luật Hôn nhân và Gia đình.", "Luật Dân sự.", "Phong tục tập quán.", "Đạo đức."], 0, "Quan hệ giữa các thành viên trong gia đình (ông bà, cháu, anh chị em...) được điều chỉnh chủ yếu bởi Luật Hôn nhân và Gia đình."],
  [169, "p6", "Điều kiện để kết hôn bao gồm:", ["Nam từ đủ 20 tuổi, nữ từ đủ 18 tuổi trở lên.", "Việc kết hôn do nam và nữ tự nguyện quyết định.", "Không bị mất năng lực hành vi dân sự và không thuộc các trường hợp cấm kết hôn.", "Cả A, B và C."], 3, "Điều kiện kết hôn gồm độ tuổi (nam đủ 20, nữ đủ 18), tự nguyện, không mất năng lực hành vi dân sự và không thuộc trường hợp cấm."],
  [170, "p6", "Thỏa thuận về chế độ tài sản của vợ chồng phải được lập dưới hình thức nào?", ["Lời nói.", "Email.", "Văn bản có công chứng hoặc chứng thực.", "Bất kỳ hình thức nào."], 2, "Thỏa thuận xác lập chế độ tài sản của vợ chồng phải lập trước khi kết hôn bằng văn bản có công chứng hoặc chứng thực."],
  [171, "p6", "Khi ly hôn, con từ đủ bao nhiêu tuổi trở lên phải được xem xét nguyện vọng trực tiếp ở với ai?", ["05 tuổi.", "07 tuổi.", "09 tuổi.", "12 tuổi."], 1, "Khi ly hôn, nếu con từ đủ 07 tuổi trở lên thì phải xem xét nguyện vọng của con."],
  [172, "p6", "Kết hôn trái pháp luật là việc nam, nữ đã đăng ký kết hôn tại cơ quan nhà nước có thẩm quyền nhưng:", ["Không tổ chức đám cưới.", "Vi phạm điều kiện kết hôn theo quy định của pháp luật.", "Không có tài sản chung.", "Đăng ký ở tỉnh khác nơi cư trú."], 1, "Kết hôn trái pháp luật là việc nam, nữ đã đăng ký kết hôn tại cơ quan có thẩm quyền nhưng vi phạm điều kiện kết hôn."],
  [173, "p6", "Khi vợ chồng ly hôn, quyền nuôi con dưới 36 tháng tuổi thông thường được giao cho ai?", ["Người có thu nhập cao hơn.", "Mẹ, trừ trường hợp mẹ không đủ điều kiện để trực tiếp trông nom, chăm sóc, nuôi dưỡng, giáo dục con hoặc cha mẹ có thỏa thuận khác phù hợp với lợi ích của con.", "Cha.", "Ông bà nội hoặc ngoại."], 1, "Con dưới 36 tháng tuổi được giao cho mẹ trực tiếp nuôi, trừ trường hợp mẹ không đủ điều kiện hoặc cha mẹ có thỏa thuận khác phù hợp lợi ích của con."],
  [174, "p7", "Hợp đồng lao động phải được giao kết theo nguyên tắc nào?", ["Tự nguyện, bình đẳng, thiện chí, hợp tác và trung thực.", "Mệnh lệnh, phục tùng.", "Do người sử dụng lao động quyết định.", "Do người lao động quyết định."], 0, "Điều 15 BLLĐ 2019: Giao kết HĐLĐ tuân theo nguyên tắc tự nguyện, bình đẳng, thiện chí, hợp tác và trung thực."],
  [175, "p7", "Thời gian thử việc đối với công việc có chức danh nghề nghiệp cần trình độ chuyên môn, kỹ thuật từ cao đẳng trở lên là không quá:", ["30 ngày.", "60 ngày.", "90 ngày.", "180 ngày."], 1, "Thời gian thử việc không quá 60 ngày đối với công việc cần trình độ chuyên môn, kỹ thuật từ cao đẳng trở lên."],
  [176, "p7", "Người sử dụng lao động có quyền đơn phương chấm dứt hợp đồng lao động khi nào?", ["Người lao động ốm đau, tai nạn lao động.", "Người lao động thường xuyên không hoàn thành công việc theo hợp đồng lao động được xác định theo tiêu chí đánh giá mức độ hoàn thành công việc trong quy chế của người sử dụng lao động.", "Lao động nữ mang thai.", "Người lao động nghỉ phép năm."], 1, "NSDLĐ có quyền đơn phương chấm dứt HĐLĐ khi NLĐ thường xuyên không hoàn thành công việc theo tiêu chí đánh giá trong quy chế."],
  [177, "p7", "Tuổi tối thiểu của người lao động là:", ["Đủ 13 tuổi.", "Đủ 15 tuổi.", "Đủ 16 tuổi.", "Đủ 18 tuổi."], 1, "Theo Điều 3 BLLĐ 2019, độ tuổi lao động tối thiểu của người lao động là đủ 15 tuổi (trừ trường hợp đặc biệt theo luật định)."],
  [178, "p7", "Có mấy loại hợp đồng lao động theo quy định của Bộ luật Lao động 2019?", ["2 loại: Hợp đồng lao động không xác định thời hạn và hợp đồng lao động xác định thời hạn.", "3 loại: Hợp đồng mùa vụ, hợp đồng xác định thời hạn và hợp đồng không xác định thời hạn.", "4 loại.", "1 loại duy nhất."], 0, "BLLĐ 2019 chỉ còn 2 loại HĐLĐ: HĐLĐ không xác định thời hạn và HĐLĐ xác định thời hạn (không quá 36 tháng)."],
  [179, "p7", "Thời giờ làm việc bình thường không quá:", ["08 giờ trong 01 ngày và 40 giờ trong 01 tuần.", "08 giờ trong 01 ngày và 48 giờ trong 01 tuần.", "10 giờ trong 01 ngày và 48 giờ trong 01 tuần.", "12 giờ trong 01 ngày và 56 giờ trong 01 tuần."], 1, "Thời giờ làm việc bình thường không quá 08 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần."],
  [180, "p7", "Tranh chấp lao động cá nhân phải được giải quyết thông qua thủ tục nào trước khi yêu cầu Tòa án?", ["Hòa giải của hòa giải viên lao động (trừ một số trường hợp không bắt buộc).", "Trọng tài lao động.", "Thủ tục khiếu nại.", "Có thể yêu cầu Tòa án giải quyết ngay."], 0, "Tranh chấp lao động cá nhân phải qua thủ tục hòa giải của hòa giải viên lao động trước khi yêu cầu Tòa án (trừ các trường hợp miễn hòa giải tại Điều 188)."],
  [181, "p7", "Người lao động được nghỉ làm việc, hưởng nguyên lương trong những ngày lễ, tết nào sau đây?", ["Tết Dương lịch, Tết Âm lịch, Ngày Chiến thắng, Ngày Quốc tế lao động, Ngày Quốc khánh.", "Giỗ Tổ Hùng Vương.", "Cả A và B.", "Chỉ có Tết Âm lịch."], 2, "NLĐ được nghỉ hưởng nguyên lương các ngày Tết Dương lịch, Tết Âm lịch, 30/4, 1/5, Quốc khánh 2/9 và Giỗ Tổ Hùng Vương (10/3 âm lịch)."],
  [182, "p7", "Tiền lương của người lao động trong thời gian thử việc ít nhất bằng:", ["70% mức lương của công việc đó.", "80% mức lương của công việc đó.", "85% mức lương của công việc đó.", "100% mức lương của công việc đó."], 2, "Tiền lương trong thời gian thử việc ít nhất phải bằng 85% mức lương của công việc đó."],
  [183, "p7", "Mỗi tuần, người lao động được nghỉ ít nhất:", ["12 giờ.", "24 giờ liên tục.", "36 giờ.", "48 giờ."], 1, "Mỗi tuần, người lao động được nghỉ ít nhất 24 giờ liên tục."],
  [184, "p7", "Sa thải là hình thức xử lý kỷ luật lao động nặng nhất được áp dụng trong trường hợp nào?", ["Người lao động tự ý bỏ việc 03 ngày trong một tháng.", "Người lao động có hành vi trộm cắp, tham ô, đánh bạc, cố ý gây thương tích, sử dụng ma túy tại nơi làm việc.", "Người lao động đi muộn về sớm.", "Người lao động không hoàn thành nhiệm vụ."], 1, "Điều 125 BLLĐ 2019: Áp dụng hình thức sa thải khi NLĐ trộm cắp, tham ô, đánh bạc, cố ý gây thương tích, sử dụng ma túy tại nơi làm việc..."],
  [185, "p7", "An toàn lao động, vệ sinh lao động là trách nhiệm của ai?", ["Người lao động.", "Người sử dụng lao động.", "Cả người lao động và người sử dụng lao động (cùng các cơ quan, tổ chức liên quan theo luật định).", "Nhà nước."], 2, "Bảo đảm an toàn, vệ sinh lao động là trách nhiệm của cả người sử dụng lao động, người lao động và các cơ quan, tổ chức liên quan."],
  [186, "p7", "Người lao động có quyền đơn phương chấm dứt hợp đồng lao động không xác định thời hạn mà không cần lý do, nhưng phải báo trước bao nhiêu ngày?", ["Ít nhất 3 ngày.", "Ít nhất 30 ngày.", "Ít nhất 45 ngày.", "Ít nhất 120 ngày."], 2, "NLĐ đơn phương chấm dứt HĐLĐ không xác định thời hạn phải báo trước ít nhất 45 ngày."],
  [187, "p7", "Giải quyết tranh chấp lao động tập thể về lợi ích thuộc thẩm quyền của chủ thể nào trước khi đình công hoặc yêu cầu giải quyết?", ["Hòa giải viên lao động.", "Hội đồng trọng tài lao động.", "Tòa án nhân dân.", "Chủ tịch Ủy ban nhân dân cấp tỉnh."], 0, "Theo Điều 195 BLLĐ 2019, tranh chấp lao động tập thể về lợi ích phải được giải quyết qua thủ tục hòa giải của hòa giải viên lao động trước khi yêu cầu Trọng tài hoặc đình công."],
  [188, "p7", "Tiền lương làm thêm giờ vào ngày nghỉ lễ, tết, ngày nghỉ có hưởng lương, ít nhất bằng bao nhiêu % so với tiền lương ngày làm việc bình thường (chưa kể tiền lương ngày lễ, tết, ngày nghỉ có hưởng lương)?", ["150%.", "200%.", "300%.", "400%."], 2, "Làm thêm giờ vào ngày nghỉ lễ, tết, ngày nghỉ có hưởng lương được trả ít nhất bằng 300% (chưa kể tiền lương ngày lễ đối với người hưởng lương ngày)."],
  [189, "p7", "Tranh chấp lao động tập thể về quyền là tranh chấp về:", ["Việc giải thích và thực hiện quy định của pháp luật lao động, thỏa ước lao động tập thể, nội quy lao động...", "Việc thương lượng, ký kết thỏa ước lao động tập thể.", "Yêu cầu thiết lập các điều kiện lao động mới cao hơn luật định.", "Tranh chấp giữa hai người sử dụng lao động."], 0, "Tranh chấp lao động tập thể về quyền là tranh chấp về giải thích và thực hiện quy định pháp luật lao động, thỏa ước tập thể, nội quy lao động..."],
  [190, "p7", "Thỏa ước lao động tập thể là:", ["Thỏa thuận giữa cá nhân người lao động và người sử dụng lao động.", "Thỏa thuận đạt được thông qua thương lượng tập thể và được các bên ký kết theo quy định của pháp luật.", "Quyết định của người sử dụng lao động.", "Quy định của pháp luật lao động."], 1, "Thỏa ước lao động tập thể là thỏa thuận đạt được thông qua thương lượng tập thể và được các bên ký kết theo quy định pháp luật."],
  [191, "p7", "Lao động nữ trong thời gian nuôi con dưới 12 tháng tuổi được nghỉ mỗi ngày bao nhiêu phút trong thời gian làm việc mà vẫn hưởng đủ lương?", ["30 phút.", "60 phút.", "90 phút.", "120 phút."], 1, "Lao động nữ nuôi con dưới 12 tháng tuổi được nghỉ mỗi ngày 60 phút trong thời gian làm việc mà vẫn hưởng đủ tiền lương."],
  [192, "p7", "Trợ cấp thôi việc được áp dụng khi chấm dứt hợp đồng lao động trong trường hợp nào?", ["Người lao động bị sa thải.", "Người lao động đơn phương chấm dứt hợp đồng trái pháp luật.", "Người lao động làm việc thường xuyên từ đủ 12 tháng trở lên chấm dứt hợp đồng lao động hợp pháp (trừ các trường hợp luật quy định khác như đủ điều kiện hưởng lương hưu, bị sa thải...).", "Người lao động bị xử lý kỷ luật kéo dài thời hạn nâng lương."], 2, "Trợ cấp thôi việc áp dụng cho NLĐ làm việc thường xuyên từ đủ 12 tháng trở lên khi chấm dứt HĐLĐ hợp pháp theo Điều 46 BLLĐ 2019."],
  [193, "p7", "Nội quy lao động phải được ban hành dưới hình thức nào?", ["Lời nói.", "Văn bản.", "Thỏa thuận miệng.", "Tin nhắn cá nhân."], 1, "NSDLĐ sử dụng từ 10 người lao động trở lên phải ban hành nội quy lao động bằng văn bản."],
  [194, "p7", "Hợp đồng lao động xác định thời hạn là hợp đồng mà trong đó hai bên xác định thời hạn, thời điểm chấm dứt hiệu lực của hợp đồng trong thời gian không quá:", ["12 tháng.", "24 tháng.", "36 tháng.", "60 tháng."], 2, "HĐLĐ xác định thời hạn có thời gian không quá 36 tháng kể từ thời điểm có hiệu lực."],
  [195, "p7", "Đình công là:", ["Sự ngừng việc tạm thời, tự nguyện và có tổ chức của người lao động nhằm mục đích giải quyết tranh chấp lao động tập thể.", "Hành vi vi phạm kỷ luật lao động.", "Quyền của người sử dụng lao động.", "Luôn luôn bất hợp pháp."], 0, "Đình công là sự ngừng việc tạm thời, tự nguyện và có tổ chức của người lao động nhằm đạt được yêu cầu trong giải quyết tranh chấp lao động tập thể."],
  [196, "p7", "Đối thoại tại nơi làm việc được tiến hành định kỳ:", ["01 năm một lần.", "06 tháng một lần.", "03 tháng một lần.", "Ít nhất 01 năm một lần (và khi có yêu cầu của một hoặc các bên hoặc khi có vụ việc theo quy định của Bộ luật Lao động 2019)."], 3, "Theo Điều 63 BLLĐ 2019, đối thoại tại nơi làm việc được tổ chức định kỳ ít nhất 01 năm một lần, khi có yêu cầu hoặc khi có vụ việc luật định."],
  [197, "p7", "Người sử dụng lao động không được sử dụng người lao động làm thêm giờ trong trường hợp nào?", ["Lao động nữ mang thai từ tháng thứ 7 trở đi (hoặc từ tháng thứ 6 nếu làm việc ở vùng cao, vùng sâu, vùng xa, biên giới, hải đảo).", "Người chưa thành niên (đủ 15 đến dưới 18 tuổi).", "Lao động nữ đang nuôi con dưới 12 tháng tuổi.", "Cả A, B và C."], 3, "Không được sử dụng lao động nữ mang thai từ tháng thứ 7 (hoặc tháng thứ 6 ở vùng đặc biệt), nuôi con dưới 12 tháng tuổi và người chưa thành niên làm thêm giờ."],
  [198, "p7", "Tổng số giờ làm thêm của người lao động trong 01 tháng không quá bao nhiêu giờ theo Bộ luật Lao động 2019?", ["20 giờ.", "30 giờ.", "40 giờ.", "60 giờ."], 2, "Theo Điều 107 BLLĐ 2019, số giờ làm thêm không quá 40 giờ trong 01 tháng."],
  [199, "p7", "Thời hiệu xử lý kỷ luật lao động thông thường là bao nhiêu tháng kể từ ngày có hành vi vi phạm?", ["03 tháng.", "06 tháng.", "12 tháng.", "24 tháng."], 1, "Thời hiệu xử lý kỷ luật lao động là 06 tháng kể từ ngày xảy ra hành vi vi phạm (12 tháng đối với vi phạm tài chính, tài sản, bí mật công nghệ/kinh doanh)."],
  [200, "p8", "Quyền tác giả đối với tác phẩm phát sinh khi nào?", ["Khi tác phẩm được đăng ký tại cơ quan nhà nước.", "Khi tác phẩm được công bố.", "Khi tác phẩm được sáng tạo và thể hiện dưới một hình thức vật chất nhất định, không phân biệt nội dung, chất lượng, hình thức, phương tiện, ngôn ngữ, đã công bố hay chưa công bố, đã đăng ký hay chưa đăng ký.", "Khi tác phẩm được sử dụng."], 2, "Quyền tác giả phát sinh tự động kể từ khi tác phẩm được sáng tạo và thể hiện dưới hình thức vật chất nhất định, không phụ thuộc đăng ký hay công bố."],
  [201, "p8", "Sáng chế được bảo hộ dưới hình thức nào?", ["Chỉ dẫn địa lý.", "Nhãn hiệu.", "Bằng độc quyền sáng chế (hoặc Bằng độc quyền giải pháp hữu ích nếu đáp ứng điều kiện tương ứng).", "Quyền tác giả."], 2, "Sáng chế được bảo hộ dưới hình thức cấp Bằng độc quyền sáng chế (hoặc Bằng độc quyền giải pháp hữu ích)."],
  [202, "p8", "Nhãn hiệu được bảo hộ trong thời hạn bao lâu?", ["5 năm.", "10 năm kể từ ngày nộp đơn, có thể gia hạn nhiều lần liên tiếp, mỗi lần 10 năm.", "20 năm.", "Vô thời hạn."], 1, "Giấy chứng nhận đăng ký nhãn hiệu có hiệu lực 10 năm kể từ ngày nộp đơn, có thể gia hạn nhiều lần liên tiếp, mỗi lần 10 năm."],
  [203, "p8", "Quyền liên quan đến quyền tác giả là quyền của tổ chức, cá nhân đối với:", ["Cuộc biểu diễn, bản ghi âm, ghi hình, chương trình phát sóng, tín hiệu vệ tinh mang chương trình được mã hóa.", "Sáng chế, kiểu dáng công nghiệp.", "Nhãn hiệu, tên thương mại.", "Bí mật kinh doanh."], 0, "Quyền liên quan đến quyền tác giả bảo hộ cuộc biểu diễn, bản ghi âm, ghi hình, chương trình phát sóng, tín hiệu vệ tinh mang chương trình được mã hóa."],
  [204, "p8", "Kiểu dáng công nghiệp được bảo hộ khi đáp ứng các điều kiện nào?", ["Có tính mới, tính sáng tạo và khả năng áp dụng công nghiệp.", "Có tính mới trên phạm vi thế giới.", "Chưa từng được bộc lộ công khai.", "Có khả năng sản xuất hàng loạt."], 0, "Kiểu dáng công nghiệp được bảo hộ nếu đáp ứng 3 điều kiện: có tính mới, có tính sáng tạo và có khả năng áp dụng công nghiệp."],
  [205, "p8", "Tên thương mại được bảo hộ khi:", ["Được đăng ký tại cơ quan nhà nước.", "Có khả năng phân biệt chủ thể kinh doanh mang tên đó với các chủ thể kinh doanh khác trong cùng lĩnh vực và khu vực kinh doanh.", "Được sử dụng rộng rãi.", "Có khả năng phân biệt và được sử dụng hợp pháp trong hoạt động kinh doanh."], 1, "Theo Điều 76 Luật SHTT, tên thương mại được bảo hộ nếu có khả năng phân biệt chủ thể kinh doanh mang tên đó với chủ thể khác trong cùng lĩnh vực và khu vực kinh doanh."],
  [206, "p8", "Đối tượng nào sau đây không được bảo hộ với danh nghĩa quyền tác giả?", ["Tác phẩm văn học, nghệ thuật, khoa học.", "Bài giảng, bài phát biểu.", "Tin tức thời sự thuần túy đưa tin.", "Chương trình máy tính, sưu tập dữ liệu."], 2, "Theo Điều 15 Luật SHTT, tin tức thời sự thuần túy đưa tin không thuộc phạm vi bảo hộ quyền tác giả."],
  [207, "p8", "Chủ sở hữu nhãn hiệu có quyền:", ["Sử dụng, cho phép người khác sử dụng nhãn hiệu.", "Ngăn cấm người khác sử dụng nhãn hiệu.", "Định đoạt nhãn hiệu.", "Cả A, B và C."], 3, "Chủ sở hữu nhãn hiệu có quyền sử dụng, cho phép người khác sử dụng, ngăn cấm người khác sử dụng và định đoạt nhãn hiệu."],
  [208, "p8", "Hành vi nào sau đây có thể bị coi là cạnh tranh không lành mạnh liên quan đến sở hữu trí tuệ?", ["Sử dụng chỉ dẫn thương mại gây nhầm lẫn.", "Đăng ký, chiếm giữ quyền sử dụng hoặc sử dụng tên miền trùng hoặc tương tự gây nhầm lẫn với nhãn hiệu, tên thương mại hoặc chỉ dẫn địa lý được bảo hộ với động cơ không lành mạnh.", "Quảng cáo nhằm so sánh trực tiếp, hạ bệ đối thủ cạnh tranh.", "Cả A, B và C."], 3, "Sử dụng chỉ dẫn thương mại gây nhầm lẫn, chiếm giữ tên miền trùng/tương tự gây nhầm lẫn, quảng cáo so sánh hạ bệ đối thủ đều là hành vi cạnh tranh không lành mạnh."],
  [209, "p8", "Quyền nhân thân của tác giả bao gồm:", ["Đặt tên cho tác phẩm.", "Đứng tên thật hoặc bút danh trên tác phẩm.", "Bảo vệ sự toàn vẹn của tác phẩm.", "Cả A, B và C."], 3, "Quyền nhân thân của tác giả gồm đặt tên, đứng tên thật/bút danh, công bố tác phẩm và bảo vệ sự toàn vẹn của tác phẩm."],
  [210, "p8", "Bí mật kinh doanh được bảo hộ khi đáp ứng điều kiện nào?", ["Không phải là hiểu biết thông thường và không dễ dàng có được.", "Khi được áp dụng trong kinh doanh sẽ tạo cho người nắm giữ lợi thế so với người không nắm giữ.", "Được chủ sở hữu bảo mật bằng các biện pháp cần thiết.", "Cả A, B và C."], 3, "Bí mật kinh doanh được bảo hộ khi không phải hiểu biết thông thường, tạo lợi thế kinh doanh và được chủ sở hữu bảo mật bằng biện pháp cần thiết."],
  [211, "p8", "Thời hạn bảo hộ quyền tác giả đối với tác phẩm điện ảnh, nhiếp ảnh, mỹ thuật ứng dụng, sân khấu là bao lâu?", ["50 năm kể từ khi tác phẩm được công bố lần đầu tiên.", "75 năm kể từ khi tác phẩm được công bố lần đầu tiên (đối với tác phẩm điện ảnh, nhiếp ảnh, mỹ thuật ứng dụng; nếu chưa công bố trong 25 năm kể từ khi định hình thì là 100 năm kể từ khi định hình).", "Suốt cuộc đời tác giả và 50 năm tiếp theo năm tác giả chết.", "30 năm kể từ ngày sáng tạo."], 1, "Theo Điều 27 Luật SHTT, tác phẩm điện ảnh, nhiếp ảnh, mỹ thuật ứng dụng có thời hạn bảo hộ 75 năm kể từ khi công bố lần đầu (hoặc 100 năm từ khi định hình nếu chưa công bố trong 25 năm)."],
  [212, "p8", "Chỉ dẫn địa lý là dấu hiệu dùng để chỉ sản phẩm có nguồn gốc từ:", ["Một quốc gia cụ thể.", "Một khu vực, địa phương, vùng lãnh thổ hay quốc gia cụ thể.", "Một doanh nghiệp nổi tiếng.", "Một cá nhân sáng tạo."], 1, "Chỉ dẫn địa lý là dấu hiệu dùng để chỉ nguồn gốc địa lý của sản phẩm từ khu vực, địa phương, vùng lãnh thổ hay quốc gia cụ thể."],
  [213, "p8", "Đối tượng nào sau đây không được bảo hộ với danh nghĩa sáng chế?", ["Quy trình sản xuất.", "Phát minh, lý thuyết khoa học, phương pháp toán học.", "Thiết bị, sản phẩm.", "Giải pháp kỹ thuật."], 1, "Theo Điều 59 Luật SHTT, phát minh, lý thuyết khoa học, phương pháp toán học không được bảo hộ với danh nghĩa sáng chế."],
  [214, "p8", "Tác giả và chủ sở hữu quyền tác giả có thể là:", ["Luôn là một.", "Hai chủ thể khác nhau.", "Chỉ có thể là cá nhân.", "Chỉ có thể là tổ chức."], 1, "Tác giả (người trực tiếp sáng tạo) và chủ sở hữu quyền tác giả (ví dụ tổ chức giao nhiệm vụ/đầu tư) có thể là hai chủ thể khác nhau."],
  [215, "p8", "Đối tượng nào sau đây được bảo hộ dưới danh nghĩa quyền liên quan?", ["Tác phẩm văn học.", "Cuộc biểu diễn của ca sĩ.", "Phần mềm máy tính.", "Kiểu dáng công nghiệp."], 1, "Cuộc biểu diễn của ca sĩ là đối tượng được bảo hộ dưới danh nghĩa quyền liên quan đến quyền tác giả."],
  [216, "p8", "Quyền tài sản trong quyền tác giả có được chuyển nhượng không?", ["Không.", "Có.", "Chỉ được chuyển quyền sử dụng.", "Tùy trường hợp."], 1, "Quyền tài sản trong quyền tác giả có thể được chuyển nhượng hoặc chuyển giao quyền sử dụng cho tổ chức, cá nhân khác."],
  [217, "p8", "\"Samsung\", \"Apple\", \"Google\" là các ví dụ tiêu biểu về:", ["Sáng chế.", "Kiểu dáng công nghiệp.", "Nhãn hiệu.", "Chỉ dẫn địa lý."], 2, "Samsung, Apple, Google là những ví dụ điển hình về nhãn hiệu thương mại nổi tiếng."],
  [218, "p8", "Thời hạn bảo hộ của Bằng độc quyền sáng chế là bao nhiêu năm kể từ ngày nộp đơn?", ["10 năm.", "15 năm.", "20 năm.", "25 năm."], 2, "Bằng độc quyền sáng chế có hiệu lực từ ngày cấp và kéo dài đến hết 20 năm kể từ ngày nộp đơn."],
  [219, "p8", "Quyền nhân thân nào của tác giả không được chuyển giao cho người khác?", ["Quyền công bố tác phẩm.", "Quyền đặt tên cho tác phẩm; đứng tên thật hoặc bút danh; bảo vệ sự toàn vẹn của tác phẩm (trừ trường hợp có thỏa thuận khác theo luật định).", "Quyền làm tác phẩm phái sinh.", "Quyền cho thuê bản gốc hoặc bản sao chương trình máy tính."], 1, "Các quyền nhân thân gắn liền với tác giả (đặt tên, đứng tên, bảo vệ sự toàn vẹn) không được chuyển nhượng (riêng quyền công bố tác phẩm có thể chuyển nhượng)."],
  [220, "p9", "Hoạt động thương mại là hoạt động nhằm mục đích:", ["Từ thiện.", "Sinh lợi.", "Quản lý nhà nước.", "Giao lưu văn hóa."], 1, "Hoạt động thương mại là hoạt động nhằm mục đích sinh lợi (mua bán hàng hóa, cung ứng dịch vụ, đầu tư, xúc tiến thương mại...)."],
  [221, "p9", "Loại hình doanh nghiệp nào có chủ sở hữu phải chịu trách nhiệm vô hạn bằng toàn bộ tài sản của mình?", ["Công ty TNHH một thành viên.", "Công ty cổ phần.", "Doanh nghiệp tư nhân.", "Doanh nghiệp tư nhân (đối với chủ doanh nghiệp tư nhân) và công ty hợp danh (đối với thành viên hợp danh)."], 3, "Chủ doanh nghiệp tư nhân và thành viên hợp danh của công ty hợp danh chịu trách nhiệm vô hạn bằng toàn bộ tài sản của mình."],
  [222, "p9", "Người đại diện theo pháp luật của doanh nghiệp là:", ["Cá nhân đại diện cho doanh nghiệp thực hiện các quyền và nghĩa vụ phát sinh từ giao dịch của doanh nghiệp, đại diện cho doanh nghiệp với tư cách người yêu cầu giải quyết việc dân sự, nguyên đơn, bị đơn, người có quyền lợi, nghĩa vụ liên quan trước Trọng tài, Tòa án.", "Chủ tịch công đoàn cơ sở.", "Kế toán trưởng.", "Cổ đông lớn nhất."], 0, "Theo Điều 12 Luật Doanh nghiệp 2020, người đại diện theo pháp luật là cá nhân đại diện cho doanh nghiệp thực hiện quyền, nghĩa vụ từ giao dịch và trước Trọng tài, Tòa án."],
  [223, "p9", "Mức phạt vi phạm hợp đồng thương mại tối đa đối với một nghĩa vụ hợp đồng vi phạm (trừ trường hợp pháp luật có quy định khác) là bao nhiêu?", ["8% giá trị phần nghĩa vụ hợp đồng bị vi phạm.", "12% giá trị hợp đồng.", "Không giới hạn.", "Do hai bên tự thỏa thuận."], 0, "Theo Điều 301 Luật Thương mại 2005, mức phạt vi phạm hợp đồng thương mại không quá 8% giá trị phần nghĩa vụ hợp đồng bị vi phạm."],
  [224, "p9", "Công ty Cổ phần bắt buộc phải có tối thiểu bao nhiêu cổ đông?", ["02 cổ đông.", "03 cổ đông.", "05 cổ đông.", "07 cổ đông."], 1, "Công ty cổ phần phải có tối thiểu 03 cổ đông và không hạn chế số lượng tối đa."],
  [225, "p9", "Loại hình doanh nghiệp nào được phép phát hành cổ phiếu?", ["Công ty TNHH.", "Doanh nghiệp tư nhân.", "Công ty Cổ phần.", "Công ty Hợp danh."], 2, "Chỉ có Công ty Cổ phần mới được phép phát hành cổ phiếu (cổ phần) để huy động vốn."],
  [226, "p9", "Phá sản là tình trạng doanh nghiệp, hợp tác xã:", ["Thua lỗ 3 năm liên tiếp.", "Mất khả năng thanh toán.", "Mất khả năng thanh toán và bị Tòa án nhân dân ra quyết định tuyên bố phá sản.", "Chủ doanh nghiệp bỏ trốn."], 2, "Phá sản là tình trạng doanh nghiệp, hợp tác xã mất khả năng thanh toán và bị Tòa án nhân dân ra quyết định tuyên bố phá sản."],
  [227, "p9", "Doanh nghiệp tư nhân có tư cách pháp nhân không?", ["Có.", "Không.", "Tùy trường hợp đăng ký.", "Có sau 3 năm hoạt động."], 1, "Doanh nghiệp tư nhân không có tư cách pháp nhân vì tài sản của doanh nghiệp không độc lập với tài sản chủ sở hữu."],
  [228, "p9", "Thành viên của Công ty TNHH chịu trách nhiệm về các khoản nợ và nghĩa vụ tài sản khác của công ty như thế nào?", ["Chịu trách nhiệm vô hạn.", "Chịu trách nhiệm hữu hạn trong phạm vi số vốn đã góp vào công ty.", "Chịu trách nhiệm bằng toàn bộ tài sản cá nhân.", "Không chịu trách nhiệm."], 1, "Thành viên Công ty TNHH chịu trách nhiệm về các khoản nợ và nghĩa vụ tài sản khác trong phạm vi số vốn đã góp vào công ty."],
  [229, "p9", "Theo Luật Doanh nghiệp (sửa đổi, bổ sung năm 2025), doanh nghiệp có nghĩa vụ thu thập, cập nhật, lưu giữ thông tin về chủ thể nào?", ["Khách hàng thân thiết.", "Chủ sở hữu hưởng lợi của doanh nghiệp.", "Toàn bộ người lao động thời vụ.", "Nhà cung cấp nước ngoài."], 1, "Theo Luật Doanh nghiệp sửa đổi, bổ sung năm 2025, doanh nghiệp có nghĩa vụ thu thập, cập nhật, lưu giữ thông tin về chủ sở hữu hưởng lợi của doanh nghiệp."],
  [230, "p9", "Thời hiệu khởi kiện áp dụng đối với các tranh chấp thương mại (trừ trường hợp pháp luật có quy định khác) theo Luật Thương mại là bao nhiêu năm?", ["01 năm.", "02 năm kể từ thời điểm quyền và lợi ích hợp pháp bị xâm phạm.", "03 năm.", "05 năm."], 1, "Theo Điều 319 Luật Thương mại 2005, thời hiệu khởi kiện tranh chấp thương mại là 02 năm kể từ thời điểm quyền và lợi ích hợp pháp bị xâm phạm."],
  [231, "p10", "Đất đai ở Việt Nam thuộc sở hữu của ai?", ["Sở hữu tư nhân.", "Sở hữu của người sử dụng đất.", "Sở hữu toàn dân do Nhà nước đại diện chủ sở hữu và thống nhất quản lý.", "Sở hữu tập thể."], 2, "Đất đai thuộc sở hữu toàn dân do Nhà nước đại diện chủ sở hữu và thống nhất quản lý."],
  [232, "p10", "Trong đời sống pháp lý, \"Sổ đỏ\" thường dùng để chỉ loại giấy tờ chứng nhận nào?", ["Giấy chứng nhận quyền sở hữu nhà ở.", "Giấy chứng nhận quyền sử dụng đất.", "Giấy chứng nhận quyền sở hữu nhà ở và quyền sử dụng đất ở.", "Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất (theo Luật Đất đai 2024)."], 3, "Theo Luật Đất đai 2024, tên gọi mới của 'Sổ đỏ' là Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất."],
  [233, "p10", "\"Phát triển bền vững\" là nguyên tắc cơ bản trong:", ["Bảo vệ môi trường.", "Luật hình sự.", "Luật dân sự.", "Luật lao động."], 0, "Phát triển bền vững là nguyên tắc cốt lõi của Luật Bảo vệ môi trường."],
  [234, "p10", "Người sử dụng đất có các quyền nào sau đây?", ["Chuyển đổi, chuyển nhượng.", "Cho thuê, cho thuê lại.", "Thừa kế, tặng cho, thế chấp.", "Tất cả các quyền trên (tùy thuộc vào hình thức sử dụng đất và quy định của Luật Đất đai 2024)."], 3, "Người sử dụng đất có các quyền chuyển đổi, chuyển nhượng, cho thuê, cho thuê lại, thừa kế, tặng cho, thế chấp... tùy hình thức sử dụng đất theo Luật Đất đai 2024."],
  [235, "p10", "Cơ quan nào có thẩm quyền giao đất, cho thuê đất đối với tổ chức trong nước theo Luật Đất đai 2024?", ["UBND cấp xã.", "UBND cấp tỉnh.", "Chính phủ.", "Bộ Nông nghiệp và Môi trường."], 1, "Theo Điều 123 Luật Đất đai 2024, UBND cấp tỉnh quyết định giao đất, cho thuê đất đối với tổ chức trong nước."],
  [236, "p10", "Hành vi nào bị nghiêm cấm trong lĩnh vực đất đai theo Luật Đất đai 2024?", ["Lấn đất, chiếm đất, hủy hoại đất.", "Vi phạm quy định của pháp luật về quản lý nhà nước về đất đai (như sử dụng đất không đúng mục đích, không đăng ký đất đai theo quy định...).", "Cản trở, gây khó khăn cho việc thực hiện quyền của người sử dụng đất.", "Cả A, B và C."], 3, "Lấn chiếm, hủy hoại đất, vi phạm quản lý nhà nước về đất đai và cản trở quyền của người sử dụng đất đều là hành vi bị nghiêm cấm."],
  [237, "p10", "Nhà nước thu hồi đất trong trường hợp nào theo Luật Đất đai 2024?", ["Vì mục đích quốc phòng, an ninh.", "Để phát triển kinh tế - xã hội vì lợi ích quốc gia, công cộng.", "Do vi phạm pháp luật về đất đai hoặc chấm dứt việc sử dụng đất theo pháp luật, tự nguyện trả lại đất, có nguy cơ đe dọa tính mạng con người...", "Cả A, B và C."], 3, "Nhà nước thu hồi đất vì quốc phòng an ninh, phát triển KT-XH vì lợi ích quốc gia/công cộng, do vi phạm pháp luật đất đai hoặc chấm dứt sử dụng theo luật."],
  [238, "p10", "Theo Luật Bảo vệ môi trường 2020, dự án đầu tư được phân loại theo mức độ tác động môi trường gồm mấy nhóm?", ["02 nhóm.", "03 nhóm.", "04 nhóm (nhóm I, nhóm II, nhóm III, nhóm IV).", "05 nhóm."], 2, "Theo Luật Bảo vệ môi trường 2020, dự án đầu tư được phân thành 04 nhóm (I, II, III, IV) dựa trên tiêu chí môi trường."],
  [239, "p10", "Giấy phép môi trường do cơ quan nào cấp theo quy định của Luật Bảo vệ môi trường?", ["Chỉ có Bộ Nông nghiệp và Môi trường.", "Chỉ có UBND cấp tỉnh.", "Cơ quan có thẩm quyền theo phân cấp của pháp luật về bảo vệ môi trường (gồm Bộ chuyên ngành/cấp tỉnh/cấp địa phương tùy dự án).", "Tòa án nhân dân."], 2, "Thẩm quyền cấp Giấy phép môi trường được phân cấp cho Bộ chuyên ngành, UBND cấp tỉnh hoặc cơ quan địa phương tùy quy mô, tính chất dự án."],
];

